INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'create_deepagent', 'Create DeepAgent', 'Backwards-compatible alias for :func:`create_agent` (kind=''deep'').', 'python_function', 'custom', '{"function_name": "create_deepagent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED\n\ndef _agent_config_payload(kind: str, cfg: dict) -> dict:\n    \"\"\"The DeepAgentConfig for a new agent, normal or deep.\n\n    `kind=\"normal\"` flips `use_deepagents` off: the platform then assembles the\n    prompt (guardrails + tool enforcement) instead of taking ours verbatim, and\n    the harness file tools no longer arrive for free — a normal agent that needs\n    to write files must list `write_file` itself.\n    \"\"\"\n    from models.deep_agent import (\n        DeepAgentConfig,\n        MiddlewareConfig,\n        SubAgentConfig,\n        create_default_backend_config,\n        create_default_guardrails_config,\n        create_default_middleware_config,\n    )\n\n    subagents = []\n    for sub in cfg.get(\"subagents\") or []:\n        if not isinstance(sub, dict) or not sub.get(\"name\"):\n            continue\n        subagents.append(\n            SubAgentConfig(\n                name=sub[\"name\"],\n                description=sub.get(\"description\") or \"\",\n                system_prompt=sub.get(\"system_prompt\") or \"\",\n                tools=list(sub.get(\"tools\") or []),\n                middleware=list(sub.get(\"middleware\") or []),\n                interrupt_on=sub.get(\"interrupt_on\") or {},\n            )\n        )\n\n    middleware = []\n    for mw in cfg.get(\"middleware\") or []:\n        if isinstance(mw, dict) and mw.get(\"type\"):\n            middleware.append(\n                MiddlewareConfig(\n                    type=mw[\"type\"],\n                    enabled=mw.get(\"enabled\", True),\n                    config=mw.get(\"config\") or {},\n                )\n            )\n    # None = \"I did not say\" → platform defaults. [] = \"I said none\" → none.\n    # Collapsing the two made a template that says \"no middleware\" silently get\n    # todo_list + filesystem + subagent (found by Agent Builder, 2026-11-01).\n    if cfg.get(\"middleware\") is None:\n        middleware = create_default_middleware_config()\n\n    return DeepAgentConfig(\n        model=cfg.get(\"model\") or None,\n        temperature=cfg.get(\"temperature\") if cfg.get(\"temperature\") is not None else 0.3,\n        system_prompt=(cfg.get(\"system_prompt\") or \"\").strip(),\n        native_tools=list(cfg.get(\"native_tools\") or []),\n        cli_tools=[],\n        custom_tools=[],\n        skills=cfg.get(\"skills\"),\n        tools=[],\n        use_deepagents=(kind != \"normal\"),\n        middleware=middleware,\n        subagents=subagents,\n        mcp_servers=cfg.get(\"mcp_servers\") or None,\n        tool_params=cfg.get(\"tool_params\") or None,\n        backend=create_default_backend_config(),\n        guardrails=create_default_guardrails_config(),\n    )\n\ndef _apply_config(agent, cfg_obj) -> list[str]:\n    \"\"\"Write a DeepAgentConfig onto the template row; returns the fields saved.\"\"\"\n    from sqlalchemy.orm.attributes import flag_modified\n\n    dumped = cfg_obj.dict()\n    agent.config = dumped\n    agent.middleware_config = [m.dict() for m in cfg_obj.middleware]\n    agent.subagents_config = [s.dict() for s in cfg_obj.subagents]\n    agent.backend_config = cfg_obj.backend.dict()\n    agent.guardrails_config = cfg_obj.guardrails.dict()\n    flag_modified(agent, \"config\")\n    saved = [\"model\", \"temperature\", \"system_prompt\", \"native_tools\", \"middleware\"]\n    if cfg_obj.subagents:\n        saved.append(\"subagents\")\n    if cfg_obj.mcp_servers:\n        saved.append(\"mcp_servers\")\n    if cfg_obj.tool_params:\n        saved.append(\"tool_params\")\n    if cfg_obj.skills:\n        saved.append(\"skills\")\n    return saved\n\ndef _as_list(value, sep: str = \",\") -> list:\n    \"\"\"Accept a real list, a JSON array string, or CSV — models send all three.\n\n    The tool schema says \"array\" now, but a model that has seen older catalog\n    text still emits \"web_search,tavily_search\". Coercing here keeps the build\n    correct instead of silently creating an agent whose tools are the\n    characters of that string (which happened once).\n    \"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [str(v).strip() for v in value if str(v).strip()]\n    if isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        if text.startswith(\"[\"):\n            try:\n                import json as _json\n\n                parsed = _json.loads(text)\n                if isinstance(parsed, list):\n                    return [str(v).strip() for v in parsed if str(v).strip()]\n            except Exception:\n                pass\n        return [part.strip() for part in text.split(sep) if part.strip()]\n    return [str(value)]\n\ndef _as_dict(value):\n    \"\"\"Accept a dict or a JSON object string.\"\"\"\n    if value is None:\n        return None\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str) and value.strip().startswith(\"{\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return parsed if isinstance(parsed, dict) else None\n        except Exception:\n            return None\n    return None\n\ndef _as_list_of_dicts(value) -> list:\n    \"\"\"Accept a list, or a JSON array string (subagents/middleware).\"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [v for v in value if isinstance(v, dict)]\n    if isinstance(value, str) and value.strip().startswith(\"[\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return [v for v in parsed if isinstance(v, dict)] if isinstance(parsed, list) else []\n        except Exception:\n            return []\n    return []\n\ndef create_agent(name: str,\n                 system_prompt: str,\n                 native_tools: list[str],\n                 kind: str = \"deep\",\n                 skills: list[str] | None = None,\n                 description: str | None = None,\n                 category: str | None = None,\n                 model: str | None = None,\n                 temperature: float = 0.3,\n                 subagents: list[dict] | None = None,\n                 middleware: list[dict] | None = None,\n                 mcp_servers: dict | None = None,\n                 tool_params: dict | None = None,\n                 agent_docs: dict | None = None) -> str:\n    \"\"\"Create an agent in the database (deep or normal). Requires human approval.\n\n    Args:\n        name: Agent name, e.g. ''case-13-weather''\n        system_prompt: Complete system prompt (what it does, how it answers, where it saves)\n        native_tools: Tool ids from pg_list_custom_tools — never guess names\n        kind: ''deep'' (harness gives ls/read_file/write_file/glob/grep, subagents, skills)\n              or ''normal'' (platform assembles the prompt; file tools must be listed here)\n        skills: Skill ids from search_skills / pg_list_skills\n        description: One or two sentences for the agent list\n        category: ''Custom'', ''Research'', ''Coding'', ...\n        model: Model name; omit for the platform default\n        temperature: 0.0–1.0 (default 0.3 — precise enough for build work)\n        subagents: [{\"name\",\"description\",\"system_prompt\",\"tools\",\"middleware\",\"interrupt_on\"}]\n        middleware: [{\"type\":\"todo_list\",\"enabled\":true,\"config\":{...}}, ...]\n        mcp_servers: {\"calendar\": {\"url\": \"http://127.0.0.1:3000\"}} — see docs/design/agent-builder.md\n        tool_params: Per-tool defaults, e.g. {\"neo4j_agent_tool\": {\"database\": \"neo4j\"}}\n        agent_docs: {\"AGENTS.md\": \"...\", \"CLAUDE.md\": \"...\"}\n\n    Returns the new agent id plus which fields took effect. Build first in your head,\n    then write a rubric, then call this — see the agent-builder skill.\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import DeepAgentTemplate\n\n    if kind not in (\"deep\", \"normal\"):\n        return f\"❌ kind must be ''deep'' or ''normal'', got {kind!r}\"\n\n    native_tools = _as_list(native_tools)\n    skills = _as_list(skills)\n    subagents = _as_list_of_dicts(subagents)\n    middleware = _as_list_of_dicts(middleware)\n    mcp_servers = _as_dict(mcp_servers)\n    tool_params = _as_dict(tool_params)\n    agent_docs = _as_dict(agent_docs)\n\n    if not native_tools:\n        return \"❌ native_tools is empty — read pg_list_custom_tools and pass the real ids\"\n\n    refusal = _approval_gate(\n        \"create_agent\",\n        {\"name\": name, \"kind\": kind, \"native_tools\": native_tools,\n         \"skills\": skills or [], \"subagents\": [s.get(\"name\") for s in (subagents or [])]},\n        f\"Create agent {name!r} ({kind}) with {len(native_tools)} tools\",\n    )\n    if refusal:\n        return refusal\n\n    db = SessionLocal()\n    try:\n        cfg_obj = _agent_config_payload(kind, {\n            \"system_prompt\": system_prompt,\n            \"native_tools\": native_tools,\n            \"skills\": skills,\n            \"model\": model,\n            \"temperature\": temperature,\n            \"subagents\": subagents,\n            \"middleware\": middleware,\n            \"mcp_servers\": mcp_servers,\n            \"tool_params\": tool_params,\n        })\n        agent = DeepAgentTemplate(\n            name=name.strip(),\n            description=(description or \"\").strip(),\n            category=category or \"Custom\",\n            config=cfg_obj.dict(),\n            middleware_config=[],\n            subagents_config=[],\n            backend_config=cfg_obj.backend.dict(),\n            guardrails_config=cfg_obj.guardrails.dict(),\n            agent_docs=agent_docs,\n            is_public=False,\n        )\n        saved = _apply_config(agent, cfg_obj)\n        db.add(agent)\n        db.commit()\n        db.refresh(agent)\n\n        return (\n            f\"✅ agent ''{name}'' created — id={agent.id}, kind={kind}\\n\"\n            f\"保存字段: {'', ''.join(saved)}\\n\"\n            f\"工具 {len(cfg_obj.native_tools)} / 技能 {len(cfg_obj.skills or [])} / \"\n            f\"子代理 {len(cfg_obj.subagents)} / MCP {len(cfg_obj.mcp_servers or {})}\\n\"\n            f\"下一步: test_agent(agent_id={agent.id}, probe=...) 用针对 rubric 的探针跑一轮。\"\n        )\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to create agent: {e}\"\n    finally:\n        db.close()\n\ndef create_deepagent(name: str,\n                     system_prompt: str,\n                     native_tools: list[str],\n                     skills: list[str] | None = None,\n                     description: str | None = None,\n                     category: str | None = None,\n                     model: str | None = None,\n                     temperature: float | None = None) -> str:\n    \"\"\"Backwards-compatible alias for :func:`create_agent` (kind=''deep'').\n\n    Two seeded agents (112 Agent Creator, 178 Research Pipeline Builder) were\n    configured with this tool id before the unified create_agent existed; the\n    DB row and its embedded code keep working because this name still resolves\n    to the same behaviour.\n    \"\"\"\n    return create_agent(\n        name=name,\n        system_prompt=system_prompt,\n        native_tools=native_tools,\n        kind=\"deep\",\n        skills=skills,\n        description=description,\n        category=category,\n        model=model,\n        temperature=temperature if temperature is not None else 0.3,\n    )", "args_schema": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "string", "description": ""}, "skills": {"type": "string", "description": ""}, "description": {"type": "string", "description": ""}, "category": {"type": "string", "description": ""}, "model": {"type": "string", "description": ""}, "temperature": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "system_prompt": {"type": "string", "description": ""}, "native_tools": {"type": "string", "description": ""}, "skills": {"type": "string", "description": ""}, "description": {"type": "string", "description": ""}, "category": {"type": "string", "description": ""}, "model": {"type": "string", "description": ""}, "temperature": {"type": "string", "description": ""}}, "required": ["name", "system_prompt", "native_tools"]}', 'string', NULL, '{"category": "agents", "order": 30, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-08-01 14:44:18.034592+00:00', '2026-11-01 04:00:09.571933+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'create_deepagent');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'create_skill', 'Create Skill', 'Create a skill the way this platform stores skills: DB row + SKILL.md on disk.

A skill is two things here — a row in `skills` and a git-tracked
`SKILL.md` under `backend/skills/personal/<owner>/<skill_id>/`. Writing only
the row (which this tool used to do, with a `db://` pseudo-path) produced a
skill that no teammate could receive, that had no folder for support files,
and that `skill(id, file=...)` could not read from.

Requires human approval.

Args:
    name: Human-readable name, e.g. ''Wechat Article Rewriter'' (id is derived)
    description: One or two sentences — this is what the agent matches on
    instructions: The SKILL.md body: steps, output contract, self-check
    tags: Categorization tags, e.g. [''writing'', ''content'']
    triggers: When it applies, e.g. [''user asks for a 公众号 article'']
    allowed_tools: Tools the skill assumes, e.g. [''read_file'', ''write_file'']
    files: Support files to write next to SKILL.md, as {relative path: content}.
           Use it for reference material the instructions point at —
           `{"references/style-guide.md": "…", "templates/outline.md": "…"}`.
           They are read on demand with skill(<id>, file="<path>"), never
           loaded with the instructions.', 'python_function', 'custom', '{"function_name": "create_skill", "code": "# --- imports ---\n\nimport json\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        parts = [\n            f\"# Skill: {found.name}\",\n            f\"**Description:** {found.description}\",\n            \"\",\n            found.instructions,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"\n\ndef _coerce_str_list(value) -> list[str] | None:\n    \"\"\"Normalise a model-supplied \"list\" into a real list of strings.\n\n    Why this exists: ``create_skill``/``update_skill`` declare ``tags: list[str]``\n    and ``triggers: list[str]``, but Python does not enforce annotations at\n    runtime. Models routinely pass arrays as JSON text (``''[\"a\", \"b\"]''``) or as a\n    comma-separated string (``\"a, b\"``). Stored verbatim in the JSON columns,\n    that string makes ``SkillResponse`` fail validation — which surfaced as a\n    500 on ``GET /api/skills/{id}`` while ``GET /api/skills`` hid it behind a\n    placeholder row.\n\n    Coerce at the boundary rather than trusting the type hint: an LLM is the\n    caller here, so the input is untrusted text in practice.\n    \"\"\"\n    if value is None:\n        return None\n    if isinstance(value, (list, tuple, set)):\n        items = list(value)\n    elif isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        parsed = None\n        try:\n            parsed = json.loads(text)\n        except (ValueError, TypeError):\n            parsed = None\n        if isinstance(parsed, list):\n            items = parsed\n        elif isinstance(parsed, dict) or parsed is None:\n            # Not JSON, or a JSON object: fall back to splitting on commas.\n            items = text.split(\",\")\n        else:\n            items = [parsed]\n    else:\n        items = [value]\n\n    out: list[str] = []\n    for item in items:\n        if item is None:\n            continue\n        text = str(item).strip()\n        if text:\n            out.append(text)\n    return out\n\nasync def create_skill(name: str, description: str, instructions: str,\n                       tags: list[str] | None = None,\n                       triggers: list[str] | None = None,\n                       allowed_tools: list[str] | None = None,\n                       files: dict[str, str] | None = None) -> str:\n    \"\"\"Create a skill the way this platform stores skills: DB row + SKILL.md on disk.\n\n    A skill is two things here — a row in `skills` and a git-tracked\n    `SKILL.md` under `backend/skills/personal/<owner>/<skill_id>/`. Writing only\n    the row (which this tool used to do, with a `db://` pseudo-path) produced a\n    skill that no teammate could receive, that had no folder for support files,\n    and that `skill(id, file=...)` could not read from.\n\n    Requires human approval.\n\n    Args:\n        name: Human-readable name, e.g. ''Wechat Article Rewriter'' (id is derived)\n        description: One or two sentences — this is what the agent matches on\n        instructions: The SKILL.md body: steps, output contract, self-check\n        tags: Categorization tags, e.g. [''writing'', ''content'']\n        triggers: When it applies, e.g. [''user asks for a 公众号 article'']\n        allowed_tools: Tools the skill assumes, e.g. [''read_file'', ''write_file'']\n        files: Support files to write next to SKILL.md, as {relative path: content}.\n               Use it for reference material the instructions point at —\n               `{\"references/style-guide.md\": \"…\", \"templates/outline.md\": \"…\"}`.\n               They are read on demand with skill(<id>, file=\"<path>\"), never\n               loaded with the instructions.\n    \"\"\"\n    from core.skills.registry import get_skill_registry\n\n    skill_id = name.lower().strip().replace(\" \", \"-\").replace(\"_\", \"-\")\n    if not description or not description.strip():\n        return \"❌ description is required — an agent matches a skill by its description\"\n    if not instructions or not instructions.strip():\n        return \"❌ instructions is empty — the SKILL.md body is the skill\"\n\n    refusal = _approval_gate(\n        \"create_skill\",\n        {\"name\": name, \"skill_id\": skill_id, \"tags\": tags or []},\n        f\"Create skill {skill_id!r} (DB row + SKILL.md on disk)\",\n    )\n    if refusal:\n        return refusal\n\n    try:\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        existing = registry.get_skill(skill_id)\n        if existing:\n            return (f\"Skill ''{skill_id}'' already exists (ID={existing.id}). \"\n                    f\"Use update_skill to modify it.\")\n\n        # The Agent Skills spec the LangChain docs follow makes `name` the\n        # identifier (the directory name). Keep the human label for the DB and\n        # the body heading, but write the id into frontmatter — a reader that\n        # loads the folder by name would otherwise mismatch.\n        skill = await registry.create_skill(\n            skill_id=skill_id,\n            name=skill_id,\n            description=description.strip(),\n            instructions=instructions.strip(),\n            tags=_coerce_str_list(tags) or [\"custom\"],\n            triggers=_coerce_str_list(triggers) or [],\n            allowed_tools=_coerce_str_list(allowed_tools) or [],\n            author=\"AI Generated\",\n        )\n\n        from core.skills.sync import db_row_to_fs\n\n        path = db_row_to_fs(skill)\n        base = Path(path).parent\n        written: list[str] = []\n        skipped: list[str] = []\n        files = _as_dict(files) or {}\n        allowed_dirs = (\"references\", \"scripts\", \"assets\")\n        for rel, content in files.items():\n            rel_str = str(rel)\n            top = rel_str.split(\"/\")[0]\n            if not rel_str.strip():\n                continue\n            if \"/\" in rel_str and top not in allowed_dirs:\n                # Spec layout: scripts/ references/ assets/. `templates/x.md` and\n                # `facts/x.md` work on disk but a spec-following reader will not\n                # look there.\n                skipped.append(\n                    f\"{rel_str} (top-level dir must be one of {'', ''.join(allowed_dirs)})\"\n                )\n                continue\n            target = (base / rel_str).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                skipped.append(f\"{rel_str} (escapes the skill folder)\")\n                continue\n            target.parent.mkdir(parents=True, exist_ok=True)\n            target.write_text(str(content), encoding=\"utf-8\")\n            written.append(str(rel))\n\n        # Verify from disk and report sizes: the agent cannot `ls` this folder\n        # (it lives under backend/skills/, outside the agent workspace), so the\n        # tool has to be the one that confirms what actually landed.\n        on_disk: list[str] = []\n        for f in sorted(base.rglob(\"*\")):\n            if f.is_file():\n                on_disk.append(f\"{f.relative_to(base)} ({f.stat().st_size} B)\")\n        missing = [rel for rel in written if not (base / rel).is_file()]\n        body = (skill.instructions or \"\")\n        unmentioned = [rel for rel in written if Path(rel).name not in body]\n\n        return (\n            f\"✅ Skill ''{skill_id}'' created (ID={skill.id}).\\n\"\n            f\"SKILL.md: {path}\\n\"\n            f\"文件夹: {Path(path).parent}\\n\"\n            f\"技能 id 可以填进 agent 的 skills 列表；\"\n            f\"support files 用 skill(\\\"{skill_id}\\\", file=\\\"<相对路径>\\\") 读。\"\n            + (f\"\\nsupport files 已写: {written}\" if written else \"\")\n            + (f\"\\n被拒绝（越界路径）: {skipped}\" if skipped else \"\")\n            + (\"\\n目录实际内容（磁盘核对）:\\n  \" + \"\\n  \".join(on_disk) if on_disk else\n               \"\\n目录实际内容: (empty)\")\n            + (f\"\\n⚠️ 写入后不存在: {missing}\" if missing else \"\")\n            + (\n                \"\\n⚠️ 正文没有提到这些文件（规范要求逐一点名并说明何时用）: \"\n                + \", \".join(unmentioned) if unmentioned else \"\"\n            )\n        )\n    except Exception as e:\n        return f\"❌ Failed to create skill: {e}\"\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED\n\ndef _as_dict(value):\n    \"\"\"Accept a dict or a JSON object string.\"\"\"\n    if value is None:\n        return None\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str) and value.strip().startswith(\"{\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return parsed if isinstance(parsed, dict) else None\n        except Exception:\n            return None\n    return None", "args_schema": {"name": {"type": "string", "description": ""}, "description": {"type": "string", "description": ""}, "instructions": {"type": "string", "description": ""}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}, "allowed_tools": {"type": "array", "description": "", "default": null}, "files": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "description": {"type": "string", "description": ""}, "instructions": {"type": "string", "description": ""}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}, "allowed_tools": {"type": "array", "description": "", "default": null}, "files": {"type": "object", "description": "", "default": null}}, "required": ["name", "description", "instructions"]}', 'string', NULL, '{"category": "skills", "order": 23, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-01 14:44:18.034633+00:00', '2026-11-01 07:50:43.246184+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'create_skill');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'delete_file', 'Delete File', 'Delete a file (or an empty directory) inside the workspace sandbox.

Use when the user asks to remove or clean up a file. Refuses to delete
non-empty directories — there is no recursive delete by design.

Args:
    file_path: Path to the file to delete (relative to the workspace or absolute)', 'python_function', 'custom', '{"function_name": "delete_file", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef delete_file(file_path: str) -> str:\n    \"\"\"Delete a file (or an empty directory) inside the workspace sandbox.\n\n    Use when the user asks to remove or clean up a file. Refuses to delete\n    non-empty directories — there is no recursive delete by design.\n\n    Args:\n        file_path: Path to the file to delete (relative to the workspace or absolute)\n    \"\"\"\n    resolved, error = _resolve_sandbox_path(file_path)\n    if error:\n        return error\n    if not resolved.exists():\n        return f\"Error: ''{file_path}'' not found\"\n    if resolved.is_dir():\n        try:\n            resolved.rmdir()\n            return f\"Removed empty directory ''{file_path}''\"\n        except OSError:\n            return (f\"Error: ''{file_path}'' is a non-empty directory — \"\n                    f\"refusing recursive delete\")\n    resolved.unlink()\n    return f\"Deleted file ''{file_path}''\"", "args_schema": {"file_path": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"file_path": {"type": "string", "description": ""}}, "required": ["file_path"]}', 'string', NULL, '{"category": "filesystem", "order": 9, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-15 08:02:47.985665+00:00', '2026-10-26 10:15:43.990719+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'delete_file');

