SELECT 'glob', 'Glob', 'Find files matching a glob pattern.

Supports patterns like "**/*.py" (all Python files) or "src/*.ts" (TypeScript in src).

Args:
    pattern: Glob pattern to match (e.g., "**/*.py", "*.md", "src/**/*.tsx")
    path: Base directory to search from (default: current directory)

Returns:
    List of matching file paths

Example:
    >>> glob("**/*.py")
    >>> glob("*.md", path="/docs")
    >>> glob("src/**/*.tsx")', 'python_function', 'custom', '{"function_name": "glob", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport subprocess as _subprocess\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef glob(pattern: str, path: str = \".\") -> str:\n    \"\"\"\n    Find files matching a glob pattern.\n\n    Supports patterns like \"**/*.py\" (all Python files) or \"src/*.ts\" (TypeScript in src).\n\n    Args:\n        pattern: Glob pattern to match (e.g., \"**/*.py\", \"*.md\", \"src/**/*.tsx\")\n        path: Base directory to search from (default: current directory)\n\n    Returns:\n        List of matching file paths\n\n    Example:\n        >>> glob(\"**/*.py\")\n        >>> glob(\"*.md\", path=\"/docs\")\n        >>> glob(\"src/**/*.tsx\")\n    \"\"\"\n    try:\n        base_path, err = _resolve_sandbox_path(path)\n        if err:\n            return err\n\n        if not base_path.exists():\n            return f\"Error: Path not found: {path}\"\n\n        # ripgrep fast path when available (rg is much faster on large trees).\n        import shutil as _shutil\n        import subprocess as _subprocess\n        if _shutil.which(\"rg\") is not None and base_path.is_dir():\n            try:\n                proc = _subprocess.run(\n                    [\"rg\", \"--files\", \"-g\", pattern, \".\"],\n                    cwd=str(base_path), capture_output=True, text=True, timeout=30,\n                )\n                out = (proc.stdout or \"\").strip()\n                if out:\n                    return \"\\n\".join(out.splitlines()[:200])\n            except Exception:\n                pass  # fall back to the Python implementation\n\n        matches = list(base_path.glob(pattern))\n\n        if not matches:\n            return f\"No files found matching pattern ''{pattern}'' in {path}\"\n\n        # Format results with relative paths\n        result_lines = []\n        for match in sorted(matches):\n            try:\n                rel_path = match.relative_to(base_path)\n                result_lines.append(str(rel_path))\n            except ValueError:\n                result_lines.append(str(match))\n\n        logger.info(f\"Glob ''{pattern}'' found {len(matches)} files\")\n        return \"\\n\".join(result_lines)\n\n    except Exception as e:\n        logger.error(f\"Error with glob pattern {pattern}: {e}\")\n        return f\"Error searching for files: {str(e)}\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}}', '{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}}, "required": ["pattern"]}', 'string', NULL, '{"category": "filesystem", "order": 7, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034571+00:00', '2026-10-26 10:15:43.990715+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'glob');

