SELECT 'graphindex_show', 'GraphIndex - Show Document', 'Show one document''s metadata from Neo4j.', 'python_function', 'custom', '{"function_name": "graphindex_show", "code": "# --- imports ---\n\nfrom typing import Annotated, List, Literal, NotRequired, Optional, Dict, Any\n\nfrom contextvars import ContextVar\n\nimport os\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\n_GRAPHINDEX_PROJECT_ID: ContextVar = ContextVar(\"_GRAPHINDEX_PROJECT_ID\", default=None)\n\ndef _get_project_id() -> Optional[int]:\n    \"\"\"Get the current project ID from the request-scoped var (set during agent execution).\"\"\"\n    pid = _GRAPHINDEX_PROJECT_ID.get()\n    if pid is not None:\n        return pid\n    pid = os.environ.get(\"GRAPHINDEX_PROJECT_ID\")\n    if pid:\n        try:\n            return int(pid)\n        except (ValueError, TypeError):\n            return None\n    return None\n\ndef _run_capturing_stdout(fn, *args, **kwargs):\n    \"\"\"Run a function and capture its stdout.\n\n    Some cmd_* functions print reports to stdout. We redirect stdout\n    into a buffer so the result shows in the agent''s tool output.\n    \"\"\"\n    import io\n    import contextlib\n    buf = io.StringIO()\n    with contextlib.redirect_stdout(buf):\n        rc = fn(*args, **kwargs)\n    return rc, buf.getvalue().rstrip()\n\ndef _make_neo4j_index():\n    \"\"\"Create a Neo4jDocumentIndex from env vars.\"\"\"\n    from learning.phase9.graphindex.index_build import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef graphindex_show(name: str, project_id: Optional[int] = None) -> str:\n    \"\"\"Show one document''s metadata from Neo4j.\n\n    Uses ``learning.phase9.graphindex.index_build.cmd_show``.\n\n    Args:\n        name: Exact document filename.\n        project_id: Optional project ID.\n    \"\"\"\n    # Request-scoped override (set by the chat route) takes precedence over the\n    # LLM-provided arg.\n    pid_override = _GRAPHINDEX_PROJECT_ID.get()\n    if pid_override is not None:\n        project_id = pid_override\n    elif not project_id:\n        project_id = _get_project_id()\n    if not project_id:\n        return (\"ERROR: no project_id provided.\")\n\n    try:\n        from learning.phase9.graphindex.index_build import cmd_show\n        idx = _make_neo4j_index()\n        rc, captured = _run_capturing_stdout(cmd_show, idx, name, project_id=project_id)\n        # cmd_show returns () → but it''s used for its print output\n        return captured or f\"## Show: {name}\\nreturn code: {rc}\"\n    except Exception as e:\n        return f\"❌ Error showing {name}: {e}\"", "args_schema": {"name": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"name": {"type": "string", "description": ""}, "project_id": {"type": "string", "description": ""}}, "required": ["name"]}', 'string', NULL, '{"category": "graph", "order": 57, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-15 09:27:26.490202+00:00', '2026-11-01 03:15:31.477524+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'graphindex_show');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'grep', 'Grep', 'Search file contents for a regex pattern.

Searches through files and returns matching lines with context.

Args:
    pattern: Regular expression pattern to search for
    path: File or directory to search (default: current directory)
    file_pattern: Optional glob pattern to filter files (e.g., "*.py")

Returns:
    Matching lines with file paths and line numbers

Example:
    >>> grep("def main", path="src/")
    >>> grep("TODO", file_pattern="*.py")
    >>> grep("import.*requests", path=".", file_pattern="*.py")', 'python_function', 'custom', '{"function_name": "grep", "code": "# --- imports ---\n\nimport re\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\nimport subprocess as _subprocess\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef grep(pattern: str, path: str = \".\", file_pattern: str = None) -> str:\n    \"\"\"\n    Search file contents for a regex pattern.\n\n    Searches through files and returns matching lines with context.\n\n    Args:\n        pattern: Regular expression pattern to search for\n        path: File or directory to search (default: current directory)\n        file_pattern: Optional glob pattern to filter files (e.g., \"*.py\")\n\n    Returns:\n        Matching lines with file paths and line numbers\n\n    Example:\n        >>> grep(\"def main\", path=\"src/\")\n        >>> grep(\"TODO\", file_pattern=\"*.py\")\n        >>> grep(\"import.*requests\", path=\".\", file_pattern=\"*.py\")\n    \"\"\"\n    import re\n\n    try:\n        base_path, err = _resolve_sandbox_path(path)\n        if err:\n            return err\n\n        if not base_path.exists():\n            return f\"Error: Path not found: {path}\"\n\n        # ripgrep fast path when available (much faster on large trees).\n        import shutil as _shutil\n        import subprocess as _subprocess\n        if _shutil.which(\"rg\") is not None and base_path.is_dir():\n            try:\n                cmd = [\"rg\", \"-n\", \"--no-heading\", \"-S\", pattern]\n                if file_pattern:\n                    cmd += [\"-g\", file_pattern]\n                cmd.append(\".\")\n                proc = _subprocess.run(\n                    cmd, cwd=str(base_path), capture_output=True, text=True, timeout=30,\n                )\n                out = (proc.stdout or \"\").strip()\n                if out:\n                    lines_out = out.splitlines()\n                    capped = lines_out[:100]\n                    text = \"\\n\".join(capped)\n                    if len(lines_out) > 100:\n                        text += f\"\\n... and {len(lines_out) - 100} more matches\"\n                    return text\n            except Exception:\n                pass  # fall back to the Python implementation\n\n        # Compile regex\n        try:\n            regex = re.compile(pattern, re.IGNORECASE)\n        except re.error as e:\n            return f\"Error: Invalid regex pattern: {e}\"\n\n        results = []\n\n        # Determine files to search\n        if base_path.is_file():\n            files_to_search = [base_path]\n        else:\n            glob_pattern = file_pattern or \"**/*\"\n            files_to_search = [f for f in base_path.glob(glob_pattern) if f.is_file()]\n            # Bound the scan: cap the number of files searched per call.\n            MAX_FILES = 500\n            if len(files_to_search) > MAX_FILES:\n                files_to_search = files_to_search[:MAX_FILES]\n\n        # Search through files\n        for file_path in files_to_search:\n            try:\n                content = file_path.read_text(encoding=\"utf-8\")\n                lines = content.split(''\\n'')\n\n                for i, line in enumerate(lines, 1):\n                    # Bound per-file scan depth too.\n                    if i > 200_000:\n                        break\n                    if regex.search(line):\n                        try:\n                            rel_path = file_path.relative_to(base_path)\n                        except ValueError:\n                            rel_path = file_path.name\n                        results.append(f\"{rel_path}:{i}: {line.strip()}\")\n\n            except (UnicodeDecodeError, PermissionError):\n                # Skip binary files or files we can''t read\n                continue\n\n        if not results:\n            return f\"No matches found for pattern ''{pattern}''\"\n\n        # Limit results to prevent huge outputs\n        max_results = 100\n        if len(results) > max_results:\n            output = \"\\n\".join(results[:max_results])\n            output += f\"\\n\\n... and {len(results) - max_results} more matches\"\n        else:\n            output = \"\\n\".join(results)\n\n        logger.info(f\"Grep ''{pattern}'' found {len(results)} matches\")\n        return output\n\n    except Exception as e:\n        logger.error(f\"Error searching with pattern {pattern}: {e}\")\n        return f\"Error searching: {str(e)}\"", "args_schema": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"pattern": {"type": "string", "description": ""}, "path": {"type": "string", "description": "", "default": "."}, "file_pattern": {"type": "string", "description": "", "default": null}}, "required": ["pattern"]}', 'string', NULL, '{"category": "filesystem", "order": 8, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034573+00:00', '2026-10-26 10:15:43.990716+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'grep');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'list_deck_templates', 'List Deck Templates', '用我：列出可选的演示模板 id。
    别用我：不是列出文档或工具。
List the available deck templates (theme + layout sets) with a short
    description of each, so the caller can pick one for doc_to_deck / gen_pptx.', 'python_function', 'custom', '{"function_name": "_run_tool", "code": "from tools.presentation_tools import list_deck_templates\n\n\nasync def _run_tool(**kwargs) -> str:\n    \"\"\"用我：列出可选的演示模板 id。     别用我：不是列出文档或工具。 List the available deck templates (theme + layout sets) with a short     description of each, so the caller can pick one for\"\"\"\n    return str(await list_deck_templates.ainvoke({**kwargs}))\n", "args_schema": {}}', '{"type": "object", "properties": {}, "required": []}', 'string', NULL, '{"category": "presentation", "order": 22, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'presentation', TRUE, NULL, '["builtin", "presentation"]', '2026-08-25 14:20:15.078101+00:00', '2026-10-31 11:06:22.628546+00:00'
