SELECT 'ls', 'List Directory', 'List directory contents with metadata.

Shows files and directories with their types and sizes.

Args:
    directory_path: Path to the directory (default: current directory)

Returns:
    Formatted list of directory contents with metadata

Example:
    >>> ls()
    >>> ls("/home/user/projects")', 'python_function', 'custom', '{"function_name": "ls", "code": "# --- imports ---\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport os\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _sandbox_roots() -> list:\n    \"\"\"Roots the filesystem tools are allowed to touch (resolved).\n\n    The FIRST root is where relative paths land and where `bash` starts, and it is\n    the **caller''s** workspace (`<install>/users/<id>/`), not the install root. That\n    distinction is the whole point: with the install root in this list, every account''s\n    tree (`users/<someone else>/…`) was an allowed path, so one person''s agent could\n    read another''s files by absolute path — and a bare `pwd` in the shell answered with\n    the shared root, which is how the agent decided to work there.\n\n    The other entries are shared by design: `data/` holds the knowledge base, and\n    `.workspace_data` / the presentation dir are tool-owned.\n    \"\"\"\n    backend_dir = Path(__file__).resolve().parent.parent\n    from services import user_roots\n\n    try:\n        private_root = user_roots.current_root()   # run binding → identity → owner\n    except Exception:  # no identity and no DB → fall back to the install root\n        private_root = backend_dir / \"outputs\"\n\n    roots = [\n        private_root,                        # this person''s tree (write_file home, bash cwd)\n        backend_dir / \".workspace_data\",     # agent workspaces (AGENTS.md etc.)\n        backend_dir / \"data\",                # uploaded documents / analysis outputs\n        backend_dir.parent / \"data\",         # repo-root data/ (sql-skill-generator etc.)\n    ]\n    # Tool-owned presentation output dir (gen_pptx) so agents can read decks.\n    present_dir = os.getenv(\"PRESENTATION_OUTPUT_DIR\", \"/tmp/langconfig-tools/presentations\")\n    roots.append(Path(present_dir))\n    return [r.resolve() for r in roots]\n\ndef _resolve_sandbox_path(path_str: str):\n    \"\"\"Resolve *path_str* and enforce the workspace sandbox.\n\n    Returns (resolved_path, None) on success, or (None, error_message)\n    when the path escapes the allowed workspace roots.\n    \"\"\"\n    try:\n        path = Path(path_str).resolve()\n    except (OSError, RuntimeError, ValueError) as e:\n        return None, f\"Error: invalid path ''{path_str}'': {e}\"\n    for root in _sandbox_roots():\n        try:\n            path.relative_to(root)\n            return path, None\n        except ValueError:\n            continue\n    return (None, f\"Error: Path ''{path_str}'' is outside the allowed workspace. \"\n                  f\"Filesystem tools are restricted to project outputs, workspace \"\n                  f\"data, uploaded documents, and presentation output.\")\n\ndef ls(directory_path: str = \".\") -> str:\n    \"\"\"\n    List directory contents with metadata.\n\n    Shows files and directories with their types and sizes.\n\n    Args:\n        directory_path: Path to the directory (default: current directory)\n\n    Returns:\n        Formatted list of directory contents with metadata\n\n    Example:\n        >>> ls()\n        >>> ls(\"/home/user/projects\")\n    \"\"\"\n    try:\n        path, err = _resolve_sandbox_path(directory_path)\n        if err:\n            return err\n\n        if not path.exists():\n            return f\"Error: Directory not found: {directory_path}\"\n\n        if not path.is_dir():\n            return f\"Error: Path is not a directory: {directory_path}\"\n\n        entries = list(path.iterdir())\n\n        if not entries:\n            return f\"Empty directory: {directory_path}\"\n\n        # Format with metadata\n        lines = []\n        for entry in sorted(entries, key=lambda x: (not x.is_dir(), x.name.lower())):\n            if entry.is_dir():\n                lines.append(f\"[DIR]  {entry.name}/\")\n            else:\n                size = entry.stat().st_size\n                if size < 1024:\n                    size_str = f\"{size}B\"\n                elif size < 1024 * 1024:\n                    size_str = f\"{size / 1024:.1f}KB\"\n                else:\n                    size_str = f\"{size / (1024 * 1024):.1f}MB\"\n                lines.append(f\"[FILE] {entry.name} ({size_str})\")\n\n        logger.info(f\"Listed {len(entries)} entries in {directory_path}\")\n        return \"\\n\".join(lines)\n\n    except Exception as e:\n        logger.error(f\"Error listing directory {directory_path}: {e}\")\n        return f\"Error listing directory: {str(e)}\"", "args_schema": {"directory_path": {"type": "string", "description": "", "default": "."}}}', '{"type": "object", "properties": {"directory_path": {"type": "string", "description": "", "default": "."}}, "required": []}', 'string', NULL, '{"category": "filesystem", "order": 3, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'filesystem', TRUE, NULL, '["builtin", "filesystem"]', '2026-08-01 14:44:18.034563+00:00', '2026-10-26 10:15:43.990708+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'ls');

