SELECT 'neo4j_get_doc', 'Neo4j - Get Document Metadata', 'Get full metadata for one Document node from Neo4j by project_id and name.

Returns enriched metadata: description, supported queries, file path, tags, etc.
Use the returned file_path with read_file to get the actual document content.

Args:
    project_id: Project ID
    name: Document name in Neo4j (use neo4j_list_docs to find names)

Returns:
    Complete document metadata

Example:
    >>> neo4j_get_doc(project_id=1, name="cfd711e3_report.pdf")', 'python_function', 'custom', '{"function_name": "neo4j_get_doc", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_get_doc(project_id: int, name: str) -> str:\n    \"\"\"\n    Get full metadata for one Document node from Neo4j by project_id and name.\n\n    Returns enriched metadata: description, supported queries, file path, tags, etc.\n    Use the returned file_path with read_file to get the actual document content.\n\n    Args:\n        project_id: Project ID\n        name: Document name in Neo4j (use neo4j_list_docs to find names)\n\n    Returns:\n        Complete document metadata\n\n    Example:\n        >>> neo4j_get_doc(project_id=1, name=\"cfd711e3_report.pdf\")\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        doc = idx.get_document(project_id, name)\n        if not doc:\n            return f\"❌ Document ''{name}'' not found in Neo4j for project_id={project_id}.\"\n        lines = [\n            f\"## Document: {doc.doc_name}\",\n            f\"**Name**: `{doc.name}`\",\n            f\"**File Path**: `{doc.file_path}`\",\n            f\"**Context Doc ID**: {doc.context_doc_id}\",\n            f\"**Doc Index ID**: {doc.doc_index_id or ''(not set)''}\",\n            f\"**Page Count**: {doc.page_count}\",\n            f\"**Description**: {doc.description or ''(none)''}\",\n            \"\",\n            \"### What this document is about\",\n            doc.what_this_document_is_about or \"(no enrichment)\",\n            \"\",\n            \"### Supported Queries\",\n        ]\n        if doc.supported_queries:\n            for q in doc.supported_queries:\n                lines.append(f\"- {q}\")\n        else:\n            lines.append(\"(none)\")\n        lines.append(\"\")\n        lines.append(\"### Tags\")\n        lines.append(f\"{'', ''.join(doc.tags) if doc.tags else ''(none)''}\")\n        lines.append(\"\")\n        lines.append(\"### File Path (for read_file)\")\n        lines.append(f\"`{doc.file_path}`\")\n        lines.append(\"\")\n        lines.append(\"*Use `read_file` with the file path above to get the full document content.*\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error getting Neo4j document: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}}, "required": ["project_id", "name"]}', 'string', NULL, '{"category": "graph", "order": 43, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034615+00:00', '2026-11-01 03:15:31.477515+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_get_doc');

