SELECT 'neo4j_list_docs', 'Neo4j - List Documents', 'List all Document nodes in Neo4j for a project with their metadata.

Neo4j stores document routing metadata (summary, supported queries, tags, file path).
Use this to discover what documents are indexed before searching.

Args:
    project_id: Project ID to list documents for

Returns:
    Formatted list of documents with enriched metadata

Example:
    >>> neo4j_list_docs(project_id=1)', 'python_function', 'custom', '{"function_name": "neo4j_list_docs", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_list_docs(project_id: int) -> str:\n    \"\"\"\n    List all Document nodes in Neo4j for a project with their metadata.\n\n    Neo4j stores document routing metadata (summary, supported queries, tags, file path).\n    Use this to discover what documents are indexed before searching.\n\n    Args:\n        project_id: Project ID to list documents for\n\n    Returns:\n        Formatted list of documents with enriched metadata\n\n    Example:\n        >>> neo4j_list_docs(project_id=1)\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        docs = idx.list_documents(project_id)\n        if not docs:\n            return f\"No documents indexed in Neo4j for project_id={project_id}.\"\n        lines = [f\"## Neo4j Documents (project {project_id}, {len(docs)} total)\", \"\"]\n        for d in docs:\n            q_count = len(d.supported_queries or [])\n            lines.append(\n                f\"- **{d.doc_name}** (`{d.name}`)  \"\n                f\"pages={d.page_count}  \"\n                f\"queries={q_count}\"\n            )\n            about = d.what_this_document_is_about or d.description or \"\"\n            if about:\n                lines.append(f\"  {about[:200]}\")\n            if d.file_path:\n                lines.append(f\"  path: `{d.file_path}`\")\n            lines.append(\"\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing Neo4j documents: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}}, "required": ["project_id"]}', 'string', NULL, '{"category": "graph", "order": 42, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034613+00:00', '2026-11-01 03:15:31.477514+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_list_docs');

