SELECT 'neo4j_query', 'Neo4j - Cypher Query', 'Run an arbitrary Cypher query against Neo4j and return results.

Use this for custom graph queries beyond the built-in document tools.
The query runs against the document index Neo4j database.

Args:
    cypher: The Cypher query string (e.g. ''MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count'')
    parameters: Optional dict of query parameters (e.g. {"pid": 1})

Returns:
    Query results as formatted text

Example:
    >>> neo4j_query("MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count ORDER BY d.page_count DESC LIMIT 5", {"pid": 1})', 'python_function', 'custom', '{"function_name": "neo4j_query", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_query(cypher: str, parameters: dict | None = None) -> str:\n    \"\"\"\n    Run an arbitrary Cypher query against Neo4j and return results.\n\n    Use this for custom graph queries beyond the built-in document tools.\n    The query runs against the document index Neo4j database.\n\n    Args:\n        cypher: The Cypher query string (e.g. ''MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count'')\n        parameters: Optional dict of query parameters (e.g. {\"pid\": 1})\n\n    Returns:\n        Query results as formatted text\n\n    Example:\n        >>> neo4j_query(\"MATCH (d:Document {project_id: $pid}) RETURN d.name, d.page_count ORDER BY d.page_count DESC LIMIT 5\", {\"pid\": 1})\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        rows = idx._run_cypher(cypher, parameters or {})\n        if not rows:\n            return \"Query returned no results.\"\n        col_names = list(rows[0].keys())\n        lines = [\"## Cypher Results\", \"\"]\n        lines.append(\"| \" + \" | \".join(col_names) + \" |\")\n        lines.append(\"| \" + \" | \".join(\"---\" for _ in col_names) + \" |\")\n        for row in rows:\n            vals = []\n            for c in col_names:\n                v = row.get(c)\n                s = str(v) if v is not None else \"NULL\"\n                if len(s) > 200:\n                    s = s[:200] + \"…\"\n                vals.append(s)\n            lines.append(\"| \" + \" | \".join(vals) + \" |\")\n        lines.append(f\"\\n*{len(rows)} row(s) returned*\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Cypher error: {e}\"", "args_schema": {"cypher": {"type": "string", "description": ""}, "parameters": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"cypher": {"type": "string", "description": ""}, "parameters": {"type": "object", "description": "", "default": null}}, "required": ["cypher"]}', 'string', NULL, '{"category": "graph", "order": 44, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034617+00:00', '2026-11-01 03:20:35.958758+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_query');

