SELECT 'neo4j_upsert_doc', 'Neo4j - Upsert Document', 'Create or update a Document node in Neo4j.

Registers a document in the graph index so it becomes discoverable
via graphindex_search / neo4j_list_docs. The actual file content
should already exist on disk at file_path.

Args:
    project_id: Project ID this document belongs to
    name: Unique document name (e.g. hash-prefixed filename)
    file_path: Absolute path to the document on disk
    description: Short description of what this document is
    tags: List of categorization tags
    doc_name: Optional display name (defaults to name)

Returns:
    Confirmation message

Example:
    >>> neo4j_upsert_doc(project_id=1, name="my_report.pdf", file_path="/data/my_report.pdf", description="Q3 financial analysis", tags=["finance", "quarterly"])', 'python_function', 'custom', '{"function_name": "neo4j_upsert_doc", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nfrom langgraph.connection import (\n    NEO4J_HTTP_URL,\n    NEO4J_HTTP_USER,\n    NEO4J_HTTP_PASSWORD,\n)\n\ndef _get_neo4j_idx():\n    \"\"\"Create a Neo4jDocumentIndex from environment variables.\"\"\"\n    from services.neo4j_document_index import Neo4jDocumentIndex\n    idx = Neo4jDocumentIndex(\n        base_url=NEO4J_HTTP_URL,\n        username=NEO4J_HTTP_USER,\n        password=NEO4J_HTTP_PASSWORD,\n    )\n    idx.ensure_constraints()\n    return idx\n\ndef neo4j_upsert_doc(project_id: int, name: str, file_path: str,\n                     description: str = \"\",\n                     tags: list[str] | None = None,\n                     doc_name: str | None = None) -> str:\n    \"\"\"\n    Create or update a Document node in Neo4j.\n\n    Registers a document in the graph index so it becomes discoverable\n    via graphindex_search / neo4j_list_docs. The actual file content\n    should already exist on disk at file_path.\n\n    Args:\n        project_id: Project ID this document belongs to\n        name: Unique document name (e.g. hash-prefixed filename)\n        file_path: Absolute path to the document on disk\n        description: Short description of what this document is\n        tags: List of categorization tags\n        doc_name: Optional display name (defaults to name)\n\n    Returns:\n        Confirmation message\n\n    Example:\n        >>> neo4j_upsert_doc(project_id=1, name=\"my_report.pdf\", file_path=\"/data/my_report.pdf\", description=\"Q3 financial analysis\", tags=[\"finance\", \"quarterly\"])\n    \"\"\"\n    try:\n        idx = _get_neo4j_idx()\n        from services.neo4j_document_index import build_document_node_properties\n        props = build_document_node_properties(\n            project_id=project_id,\n            context_doc_id=0,\n            doc_index_id=None,\n            name=name,\n            file_path=file_path,\n            description=description,\n            tags=tags or [],\n        )\n        if doc_name:\n            props[\"doc_name\"] = doc_name\n        idx.upsert_document(project_id, name, file_path, properties=props)\n        display = doc_name or name\n        return f\"✅ Document ''{display}'' upserted in Neo4j for project {project_id}.\"\n    except Exception as e:\n        return f\"❌ Error upserting document: {e}\"", "args_schema": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": ""}, "description": {"type": "string", "description": "", "default": ""}, "tags": {"type": "array", "description": "", "default": null}, "doc_name": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": ""}, "name": {"type": "string", "description": ""}, "file_path": {"type": "string", "description": ""}, "description": {"type": "string", "description": "", "default": ""}, "tags": {"type": "array", "description": "", "default": null}, "doc_name": {"type": "string", "description": "", "default": null}}, "required": ["project_id", "name", "file_path"]}', 'string', NULL, '{"category": "graph", "order": 45, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'retrieval', TRUE, NULL, '["builtin", "retrieval"]', '2026-08-01 14:44:18.034619+00:00', '2026-11-01 03:20:35.958761+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'neo4j_upsert_doc');

