SELECT 'pg_get_agent', 'PG - Get Agent Config', 'Get the full configuration of a DeepAgent by its ID.

Returns system prompt, tools, skills, model, temperature, subagents, and middleware config.

Args:
    agent_id: The numeric ID of the agent (use pg_list_agents to find IDs)

Returns:
    Complete agent configuration in a readable format

Example:
    >>> pg_get_agent(agent_id=1)', 'python_function', 'custom', '{"function_name": "pg_get_agent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_get_agent(agent_id: int) -> str:\n    \"\"\"\n    Get the full configuration of a DeepAgent by its ID.\n\n    Returns system prompt, tools, skills, model, temperature, subagents, and middleware config.\n\n    Args:\n        agent_id: The numeric ID of the agent (use pg_list_agents to find IDs)\n\n    Returns:\n        Complete agent configuration in a readable format\n\n    Example:\n        >>> pg_get_agent(agent_id=1)\n    \"\"\"\n    from models.deep_agent import DeepAgentTemplate\n    db = _get_pg_session()\n    try:\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\n        if not agent:\n            return f\"❌ Agent with id={agent_id} not found.\"\n        cfg = agent.config or {}\n        lines = [\n            f\"## Agent: {agent.name} (id={agent.id})\",\n            f\"**Description**: {agent.description or ''(no description)''}\",\n            f\"**Category**: {agent.category}\",\n            f\"**Model**: {cfg.get(''model'', ''not set'')}\",\n            f\"**Temperature**: {cfg.get(''temperature'', 0.7)}\",\n            f\"**Use DeepAgents**: {cfg.get(''use_deepagents'', True)}\",\n            \"\",\n            \"### System Prompt\",\n            \"```\",\n            cfg.get(\"system_prompt\", \"(empty)\")[:2000],\n            \"```\" if len(cfg.get(\"system_prompt\", \"\")) <= 2000 else \"```\\n*...truncated*\",\n            \"\",\n            \"### Tools\",\n            f\"- Native tools: {cfg.get(''native_tools'', [])}\",\n            f\"- Skills: {cfg.get(''skills'', [])}\",\n            f\"- Custom tools: {cfg.get(''custom_tools'', [])}\",\n            \"\",\n            \"### Subagents\",\n        ]\n        subagents = cfg.get(\"subagents\", []) or agent.subagents_config or []\n        if subagents:\n            for s in subagents:\n                name = s.get(\"name\") if isinstance(s, dict) else getattr(s, \"name\", \"?\")\n                desc = s.get(\"description\") if isinstance(s, dict) else getattr(s, \"description\", \"\")\n                lines.append(f\"- **{name}**: {desc}\")\n        else:\n            lines.append(\"(none)\")\n\n        # Middleware is not decoration on this platform — it *creates* tools.\n        # `handoff` generates one `transfer_to_<step>` per step and swaps the\n        # prompt/tools per step; `todo_list` generates write_todos/read_todos;\n        # `hitl` gates calls. A reviewer that only reads `native_tools` therefore\n        # concludes \"no handoff, no approval\" about agents that have both — which\n        # is exactly what the 12-case audit did on 2026-11-01.\n        lines.append(\"\")\n        lines.append(\"### Middleware (these add or gate tools)\")\n        middleware = cfg.get(\"middleware\") or agent.middleware_config or []\n        if middleware:\n            for m in middleware:\n                if not isinstance(m, dict):\n                    continue\n                mtype = m.get(\"type\") or \"?\"\n                conf = m.get(\"config\") or {}\n                enabled = m.get(\"enabled\", True)\n                detail = f\"- **{mtype}** (enabled={enabled})\"\n                if mtype in (\"handoff\", \"human_in_the_loop_recall\") and isinstance(conf.get(\"steps\"), dict):\n                    bits = []\n                    for step, spec in conf[\"steps\"].items():\n                        spec = spec or {}\n                        to = [t.get(\"to\") for t in (spec.get(\"transfers\") or []) if isinstance(t, dict)]\n                        prompt = (spec.get(\"system_prompt\") or \"\").strip()\n                        if prompt:\n                            # Full text, not a prefix: update_agent replaces the\n                            # whole middleware field, so a caller that wants to\n                            # change one step must be able to reproduce the other\n                            # two verbatim. Truncating here forced a rewrite from\n                            # stale local copies (Agent Builder refused, correctly).\n                            snippet = (\n                                f\" prompt[{len(prompt)}c]:\\n      \"\n                                + prompt.replace(\"\\n\", \"\\n      \")\n                            )\n                        else:\n                            snippet = \" prompt=(empty)\"\n                        bits.append(\n                            f\"{step} → {to or ''(terminal)''} tools={spec.get(''tools'') or []}{snippet}\"\n                        )\n                    detail += \"\\n  \" + \"\\n  \".join(bits)\n                elif mtype in (\"hitl\", \"human_in_the_loop\"):\n                    policy = conf.get(\"interrupt_on\") or m.get(\"interrupt_on\") or {}\n                    detail += f\" interrupt_on={sorted(policy) if isinstance(policy, dict) else policy}\"\n                elif conf:\n                    detail += f\" config={str(conf)[:200]}\"\n                lines.append(detail)\n        else:\n            lines.append(\"(none)\")\n        lines.append(\"\")\n        lines.append(f\"**Version**: {agent.version} | **Public**: {agent.is_public} | **Usage**: {agent.usage_count}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error getting agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"agent_id": {"type": "integer", "description": ""}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "database", "order": 36, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034604+00:00', '2026-11-01 06:53:26.414769+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_get_agent');

