SELECT 'pg_list_agents', 'PG - List Agents', 'List all DeepAgent templates from the database with name, category, and config summary.

Use this to browse available agent configurations before selecting one.

Args:
    category: Optional category filter (e.g. ''Research'', ''Coding'', ''Custom'')

Returns:
    Formatted list of agents with id, name, category, model, and tool count

Example:
    >>> pg_list_agents()
    >>> pg_list_agents(category="Research")', 'python_function', 'custom', '{"function_name": "pg_list_agents", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_agents(category: str | None = None) -> str:\n    \"\"\"\n    List all DeepAgent templates from the database with name, category, and config summary.\n\n    Use this to browse available agent configurations before selecting one.\n\n    Args:\n        category: Optional category filter (e.g. ''Research'', ''Coding'', ''Custom'')\n\n    Returns:\n        Formatted list of agents with id, name, category, model, and tool count\n\n    Example:\n        >>> pg_list_agents()\n        >>> pg_list_agents(category=\"Research\")\n    \"\"\"\n    from models.deep_agent import DeepAgentTemplate\n    db = _get_pg_session()\n    try:\n        query = db.query(DeepAgentTemplate).order_by(DeepAgentTemplate.updated_at.desc())\n        if category:\n            query = query.filter(DeepAgentTemplate.category == category)\n        agents = query.all()\n        if not agents:\n            return \"No agents found.\" if not category else f\"No agents found in category ''{category}''.\"\n        lines = [f\"## DeepAgent Templates ({len(agents)} total)\", \"\"]\n        for a in agents:\n            cfg = a.config or {}\n            tools = cfg.get(\"native_tools\", [])\n            skills = cfg.get(\"skills\", [])\n            model = cfg.get(\"model\", \"not set\")\n            lines.append(\n                f\"- **{a.name}** (id={a.id})  \"\n                f\"`{a.category}`  model=`{model}`  \"\n                f\"tools={len(tools)}  skills={len(skills)}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing agents: {e}\"\n    finally:\n        db.close()", "args_schema": {"category": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"category": {"type": "string", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "database", "order": 35, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034602+00:00', '2026-11-01 03:15:31.477508+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_agents');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'pg_list_custom_tools', 'PG - List Custom Tools', 'List all custom (user-created) tools with their type, description, and usage stats.

Custom tools extend agent capabilities with API integrations, database connectors,
image generators, and custom Python functions.

Args:
    tool_type: Optional filter by type (api, notification, image_video, database, data_transform, python_function)

Returns:
    Formatted list of custom tools

Example:
    >>> pg_list_custom_tools()
    >>> pg_list_custom_tools(tool_type="database")', 'python_function', 'custom', '{"function_name": "pg_list_custom_tools", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_custom_tools(tool_type: str | None = None) -> str:\n    \"\"\"\n    List all custom (user-created) tools with their type, description, and usage stats.\n\n    Custom tools extend agent capabilities with API integrations, database connectors,\n    image generators, and custom Python functions.\n\n    Args:\n        tool_type: Optional filter by type (api, notification, image_video, database, data_transform, python_function)\n\n    Returns:\n        Formatted list of custom tools\n\n    Example:\n        >>> pg_list_custom_tools()\n        >>> pg_list_custom_tools(tool_type=\"database\")\n    \"\"\"\n    from models.custom_tool import CustomTool\n    db = _get_pg_session()\n    try:\n        query = db.query(CustomTool).order_by(CustomTool.usage_count.desc())\n        if tool_type:\n            query = query.filter(CustomTool.tool_type == tool_type)\n        tools = query.all()\n        if not tools:\n            return \"No custom tools found.\" if not tool_type else f\"No custom tools of type ''{tool_type}'' found.\"\n        lines = [f\"## Custom Tools ({len(tools)} total)\", \"\"]\n        for t in tools:\n            lines.append(\n                f\"- **{t.name}** (`{t.tool_id}`)  \"\n                f\"type={t.tool_type.value}  \"\n                f\"template={t.template_type.value if t.template_type else ''custom''}  \"\n                f\"used={t.usage_count}x\"\n            )\n            if t.description:\n                lines.append(f\"  {t.description[:150]}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing custom tools: {e}\"\n    finally:\n        db.close()", "args_schema": {"tool_type": {"type": "string", "description": "", "default": null}}}', '{"type": "object", "properties": {"tool_type": {"type": "string", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "database", "order": 41, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034611+00:00', '2026-11-01 03:15:31.477513+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_custom_tools');

