SELECT 'pg_list_documents', 'PG - List Documents', 'List all context documents (uploaded files) with their metadata.

Documents are the source files uploaded for RAG/GraphIndex processing.
Each document has a file_path on disk and may be indexed in Neo4j.

Args:
    project_id: Optional project ID to filter by

Returns:
    Formatted list of documents with metadata

Example:
    >>> pg_list_documents()
    >>> pg_list_documents(project_id=1)', 'python_function', 'custom', '{"function_name": "pg_list_documents", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_documents(project_id: int | None = None) -> str:\n    \"\"\"\n    List all context documents (uploaded files) with their metadata.\n\n    Documents are the source files uploaded for RAG/GraphIndex processing.\n    Each document has a file_path on disk and may be indexed in Neo4j.\n\n    Args:\n        project_id: Optional project ID to filter by\n\n    Returns:\n        Formatted list of documents with metadata\n\n    Example:\n        >>> pg_list_documents()\n        >>> pg_list_documents(project_id=1)\n    \"\"\"\n    from models.core import ContextDocument\n    db = _get_pg_session()\n    try:\n        query = db.query(ContextDocument).order_by(ContextDocument.updated_at.desc())\n        if project_id is not None:\n            query = query.filter(ContextDocument.project_id == project_id)\n        docs = query.all()\n        if not docs:\n            return \"No documents found.\" if project_id is None else f\"No documents found for project_id={project_id}.\"\n        lines = [f\"## Documents ({len(docs)} total)\", \"\"]\n        for d in docs:\n            lines.append(\n                f\"- **{d.filename}** (id={d.id})  \"\n                f\"type={d.document_type.value}  \"\n                f\"size={d.file_size}B  \"\n                f\"index={d.indexing_status.value}  \"\n                f\"project={d.project_id}\"\n            )\n            if d.description:\n                lines.append(f\"  {d.description[:150]}\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing documents: {e}\"\n    finally:\n        db.close()", "args_schema": {"project_id": {"type": "integer", "description": "", "default": null}}}', '{"type": "object", "properties": {"project_id": {"type": "integer", "description": "", "default": null}}, "required": []}', 'string', NULL, '{"category": "database", "order": 40, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034610+00:00', '2026-11-01 03:15:31.477512+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_documents');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'pg_list_projects', 'PG - List Projects', 'List projects: id, name, document count, indexing status.

Projects group documents and workflows, and are the scope for the
graphindex/doc_index retrieval tools. Use it to find a project id — not to
read a project''s documents.

Args:
    limit: Maximum number of projects to return (default 50).

Returns:
    Formatted list of projects

Example:
    >>> pg_list_projects(limit=10)', 'python_function', 'custom', '{"function_name": "pg_list_projects", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_projects(limit: int = 50) -> str:\n    \"\"\"\n    List projects: id, name, document count, indexing status.\n\n    Projects group documents and workflows, and are the scope for the\n    graphindex/doc_index retrieval tools. Use it to find a project id — not to\n    read a project''s documents.\n\n    Args:\n        limit: Maximum number of projects to return (default 50).\n\n    Returns:\n        Formatted list of projects\n\n    Example:\n        >>> pg_list_projects(limit=10)\n    \"\"\"\n    from models.core import Project, ContextDocument\n    from sqlalchemy import func\n    db = _get_pg_session()\n    try:\n        projects = db.query(\n            Project,\n            func.count(ContextDocument.id).label(\"doc_count\")\n        ).outerjoin(\n            ContextDocument, ContextDocument.project_id == Project.id\n        ).group_by(Project.id).order_by(Project.updated_at.desc()).limit(\n            max(1, int(limit or 50))\n        ).all()\n        if not projects:\n            return \"No projects found.\"\n        lines = [\"## Projects\", \"\"]\n        for proj, doc_count in projects:\n            lines.append(\n                f\"- **{proj.name}** (id={proj.id})  \"\n                f\"status=`{proj.status.value}`  \"\n                f\"docs={doc_count}  \"\n                f\"index={proj.indexing_status.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing projects: {e}\"\n    finally:\n        db.close()", "args_schema": {"limit": {"type": "integer", "description": "", "default": 50}}}', '{"type": "object", "properties": {"limit": {"type": "integer", "description": "", "default": 50}}, "required": []}', 'string', NULL, '{"category": "database", "order": 39, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034608+00:00', '2026-11-01 03:15:31.477511+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_projects');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'pg_list_skills', 'PG - List Skills', 'List skills in the database: id, description, tags, usage count.

Skills are reusable capabilities an agent can load on demand; use this to
find the id to pass to the `skill` tool. Use it when the user asks what
skills exist — not for running a skill.

Args:
    limit: Maximum number of skills to return (default 50, most used first).

Returns:
    Formatted list of available skills

Example:
    >>> pg_list_skills(limit=10)', 'python_function', 'custom', '{"function_name": "pg_list_skills", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_skills(limit: int = 50) -> str:\n    \"\"\"\n    List skills in the database: id, description, tags, usage count.\n\n    Skills are reusable capabilities an agent can load on demand; use this to\n    find the id to pass to the `skill` tool. Use it when the user asks what\n    skills exist — not for running a skill.\n\n    Args:\n        limit: Maximum number of skills to return (default 50, most used first).\n\n    Returns:\n        Formatted list of available skills\n\n    Example:\n        >>> pg_list_skills(limit=10)\n    \"\"\"\n    from models.skill import Skill\n    db = _get_pg_session()\n    try:\n        skills = (\n            db.query(Skill)\n            .order_by(Skill.usage_count.desc())\n            .limit(max(1, int(limit or 50)))\n            .all()\n        )\n        if not skills:\n            return \"No skills found in the database.\"\n        lines = [f\"## Skills ({len(skills)} total)\", \"\"]\n        for s in skills:\n            tags = \", \".join(s.tags or []) if s.tags else \"\"\n            tag_str = f\"  tags=[{tags}]\" if tags else \"\"\n            lines.append(\n                f\"- **{s.name}** (`{s.skill_id}`){tag_str}\\n\"\n                f\"  {s.description[:120]}{''…'' if len(s.description) > 120 else ''''}\\n\"\n                f\"  used {s.usage_count}x | source={s.source_type.value}\"\n            )\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing skills: {e}\"\n    finally:\n        db.close()", "args_schema": {"limit": {"type": "integer", "description": "", "default": 50}}}', '{"type": "object", "properties": {"limit": {"type": "integer", "description": "", "default": 50}}, "required": []}', 'string', NULL, '{"category": "database", "order": 37, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034606+00:00', '2026-11-01 03:15:31.477510+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_skills');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'pg_list_tables', 'PG - List Tables', 'List all tables and views in a PostgreSQL schema with row counts.

Use this to discover what tables exist in the database before querying.

Args:
    schema_name: Schema name to list (default: ''public'')

Returns:
    Formatted table list with type (table/view) and estimated row count

Example:
    >>> pg_list_tables()
    >>> pg_list_tables(schema_name="public")', 'python_function', 'custom', '{"function_name": "pg_list_tables", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\ndef _get_pg_session():\n    \"\"\"Get a sync PostgreSQL session via SessionLocal.\"\"\"\n    from db.database import SessionLocal\n    return SessionLocal()\n\ndef pg_list_tables(schema_name: str = \"public\") -> str:\n    \"\"\"\n    List all tables and views in a PostgreSQL schema with row counts.\n\n    Use this to discover what tables exist in the database before querying.\n\n    Args:\n        schema_name: Schema name to list (default: ''public'')\n\n    Returns:\n        Formatted table list with type (table/view) and estimated row count\n\n    Example:\n        >>> pg_list_tables()\n        >>> pg_list_tables(schema_name=\"public\")\n    \"\"\"\n    import sqlalchemy as sa\n    db = _get_pg_session()\n    try:\n        conn = db.connection()\n        # pg_stat_user_tables uses relname; fall back to information_schema for reliability\n        result = conn.execute(sa.text(\n            \"\"\"\n            SELECT\n                relname AS name,\n                ''table'' AS type,\n                n_live_tup AS estimated_rows\n            FROM pg_catalog.pg_stat_user_tables\n            WHERE schemaname = :schema\n            UNION ALL\n            SELECT\n                viewname AS name,\n                ''view'' AS type,\n                0 AS estimated_rows\n            FROM pg_catalog.pg_views\n            WHERE schemaname = :schema\n            ORDER BY name\n            \"\"\"\n        ), {\"schema\": schema_name})\n        rows = result.fetchall()\n        if not rows:\n            return f\"No tables found in schema ''{schema_name}''.\"\n        lines = [f\"## Tables in schema ''{schema_name}''\", \"\"]\n        for r in rows:\n            lines.append(f\"- **{r.name}** ({r.type}, ~{r.estimated_rows} rows)\")\n        return \"\\n\".join(lines)\n    except Exception as e:\n        return f\"❌ Error listing tables: {e}\"\n    finally:\n        db.close()", "args_schema": {"schema_name": {"type": "string", "description": "", "default": "public"}}}', '{"type": "object", "properties": {"schema_name": {"type": "string", "description": "", "default": "public"}}, "required": []}', 'string', NULL, '{"category": "database", "order": 31, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'database', TRUE, NULL, '["builtin", "database"]', '2026-08-01 14:44:18.034594+00:00', '2026-11-01 03:15:31.477502+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'pg_list_tables');

