SELECT 'python_execute', 'Python Execute', 'Execute Python code and return stdout + stderr.', 'python_function', 'custom', '{"function_name": "python_execute", "code": "# --- imports ---\n\nimport os as _os\n\nimport sys as _sys\n\nimport subprocess as _subprocess\n\nimport tempfile as _tempfile\n\nimport textwrap as _textwrap\n\ndef python_execute(code: str, timeout: int = 30) -> str:\n    \"\"\"\n    Execute Python code and return stdout + stderr.\n\n    WARNING: Code runs in the same process. Only trusted agents should call this.\n\n    Args:\n        code: Python code to execute\n        timeout: Max execution time in seconds\n\n    Returns:\n        Combined stdout and stderr output.\n    \"\"\"\n    try:\n        # Wrap code to capture stdout\n        wrapper_code = (\n            \"import sys, io, traceback\\n\"\n            \"_buffer = io.StringIO()\\n\"\n            \"sys.stdout = _buffer\\n\"\n            \"sys.stderr = _buffer\\n\"\n            \"try:\\n\"\n            + _textwrap.indent(code, ''    '') + \"\\n\"\n            \"except Exception:\\n\"\n            \"    traceback.print_exc()\\n\"\n            \"finally:\\n\"\n            \"    sys.stdout = sys.__stdout__\\n\"\n            \"    sys.stderr = sys.__stderr__\\n\"\n            \"    print(_buffer.getvalue(), end='''')\\n\"\n        )\n        with _tempfile.TemporaryDirectory() as tmpdir:\n            result = _subprocess.run(\n                # -I = isolated mode: ignores PYTHON* env vars and user\n                # site-packages; cwd is a throwaway temp dir so the code can''t\n                # read/write repo files by relative path.\n                [_sys.executable, \"-I\", \"-c\", wrapper_code],\n                capture_output=True,\n                text=True,\n                timeout=timeout,\n                cwd=tmpdir,\n                env={k: v for k, v in _os.environ.items() if k in (\"PATH\", \"HOME\", \"TEMP\", \"TMPDIR\")}\n            )\n        output = result.stdout or \"\"\n        if result.stderr:\n            output += f\"\\n--- stderr ---\\n{result.stderr}\"\n        if result.returncode != 0 and not output:\n            output = f\"❌ Exit code: {result.returncode}\"\n        return output if output else \"✅ Code executed (no output)\"\n    except _subprocess.TimeoutExpired:\n        return f\"❌ Timed out after {timeout}s\"\n    except Exception as e:\n        return f\"❌ Execution Error: {e}\"", "args_schema": {"code": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}}}', '{"type": "object", "properties": {"code": {"type": "string", "description": ""}, "timeout": {"type": "integer", "description": "", "default": 30}}, "required": ["code"]}', 'string', NULL, '{"category": "analysis", "order": 61, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'data', TRUE, NULL, '["builtin", "data"]', '2026-08-01 14:44:18.034625+00:00', '2026-11-01 03:15:31.477519+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'python_execute');

