SELECT 'test_agent', 'Test Agent (probe run)', 'Run one or more probes against an agent in ONE session and report what happened.

The probe must target the rubric — "hi" proves nothing. Runs through the same
HTTP chat path a user uses, so a pass here means the agent works where the user
will use it.

Use `probes` when a criterion needs several turns (a state machine that must
walk stage 1 → 2 → 3, or "the user says the earlier answer was wrong" which
only means something after two turns). Each message is sent in order in the
same session, and each turn gets its own tool sequence.

Args:
    agent_id: Agent to test
    probe: One message to send (write it against your rubric criteria)
    probes: Several messages, sent in order in the same session. Use this
            instead of `probe` for multi-turn criteria.
    max_seconds: Wall-clock cap for the whole run (all turns together)

Returns: per-turn tool sequence, elapsed time and answer text, then a total.', 'python_function', 'custom', '{"function_name": "test_agent", "code": "# --- imports ---\n\nimport asyncio\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport httpx\n\nimport os\n\nasync def test_agent(agent_id: int, probe: str = \"\", probes: list[str] | None = None,\n                    max_seconds: int = 120) -> str:\n    \"\"\"Run one or more probes against an agent in ONE session and report what happened.\n\n    The probe must target the rubric — \"hi\" proves nothing. Runs through the same\n    HTTP chat path a user uses, so a pass here means the agent works where the user\n    will use it.\n\n    Use `probes` when a criterion needs several turns (a state machine that must\n    walk stage 1 → 2 → 3, or \"the user says the earlier answer was wrong\" which\n    only means something after two turns). Each message is sent in order in the\n    same session, and each turn gets its own tool sequence.\n\n    Args:\n        agent_id: Agent to test\n        probe: One message to send (write it against your rubric criteria)\n        probes: Several messages, sent in order in the same session. Use this\n                instead of `probe` for multi-turn criteria.\n        max_seconds: Wall-clock cap for the whole run (all turns together)\n\n    Returns: per-turn tool sequence, elapsed time and answer text, then a total.\n    \"\"\"\n    import asyncio\n    import os\n    import time\n\n    import httpx\n\n    steps = list(probes or [])\n    if not steps and probe:\n        steps = [probe]\n    steps = [str(m).strip() for m in steps if str(m).strip()]\n    if not steps:\n        return \"❌ test_agent needs `probe` or `probes` — an empty probe proves nothing\"\n\n    base = os.getenv(\"LANGCONFIG_API_BASE\", \"http://127.0.0.1:8765\").rstrip(\"/\")\n    started = time.time()\n    sid = \"\"\n    try:\n        # Async on purpose. As a sync tool this ran in a worker thread while the\n        # caller''s event loop was busy with the outer run; the probe''s own\n        # streaming request then waited for that loop and died of a read timeout\n        # (measured: three attempts, 40/90/180s, all ReadTimeout while the same\n        # probe run from outside finished in 11.5s).\n        async with httpx.AsyncClient(timeout=httpx.Timeout(60.0, read=max_seconds + 30)) as client:\n            started_session = await client.post(f\"{base}/api/chat/start\", json={\"agent_id\": agent_id})\n            if started_session.status_code != 200:\n                return (f\"❌ 无法为 agent {agent_id} 开会话: HTTP {started_session.status_code} \"\n                        f\"{started_session.text[:200]}\")\n            sid = started_session.json()[\"session_id\"]\n\n            turns: list[dict] = []\n            timed_out = False\n            for index, message in enumerate(steps, 1):\n                tools: list[str] = []\n                answer_parts: list[str] = []\n                turn_started = time.time()\n\n                async def _one_turn() -> None:\n                    async with client.stream(\n                        \"POST\", f\"{base}/api/chat/message/stream\",\n                        json={\"session_id\": sid, \"message\": message},\n                    ) as resp:\n                        async for raw in resp.aiter_lines():\n                            if time.time() - started > max_seconds:\n                                return\n                            if not raw or not raw.startswith(\"data: \"):\n                                continue\n                            try:\n                                import json as _json\n                                event = _json.loads(raw[6:])\n                            except Exception:\n                                continue\n                            if event.get(\"type\") == \"tool_start\":\n                                tools.append(event.get(\"tool_name\") or \"?\")\n                            elif event.get(\"type\") == \"chunk\":\n                                answer_parts.append(event.get(\"content\") or \"\")\n                            elif event.get(\"type\") in (\"complete\", \"stopped\", \"interrupt\"):\n                                return\n\n                turn_note = \"\"\n                for attempt in (1, 2):\n                    try:\n                        # A turn that never closes its stream used to hang the\n                        # whole call until the client read-timeout fired (354s on\n                        # a handoff agent). Cap each turn; retry once, because the\n                        # usual cause is sending the next message while the server\n                        # is still finishing the previous run.\n                        await asyncio.wait_for(_one_turn(), timeout=min(max_seconds, 150))\n                        break\n                    except Exception as _exc:  # noqa: BLE001\n                        turn_note = type(_exc).__name__\n                        if attempt == 2:\n                            break\n                        await asyncio.sleep(2.0)\n                if False:  # placeholder kept out of the async-for shape\n                        if not raw or not raw.startswith(\"data: \"):\n                            continue\n                turns.append({\n                    \"n\": index, \"message\": message, \"tools\": tools,\n                    \"answer\": \"\".join(answer_parts).strip(),\n                    \"elapsed\": round(time.time() - turn_started, 1),\n                    \"note\": turn_note,\n                })\n                await asyncio.sleep(1.5)  # let the server close the previous run\n                if timed_out or turn_note:\n                    break\n    except Exception as e:\n        return f\"❌ test_agent failed: {type(e).__name__}: {e} (session={sid})\"\n\n    elapsed = round(time.time() - started, 1)\n    verdict = \"超时（未跑完）\" if timed_out else \"跑完\"\n    lines = [\n        f\"## test_agent(agent_id={agent_id}) — {verdict} in {elapsed}s \"\n        f\"({len(turns)}/{len(steps)} 轮)\",\n        f\"session: {sid}\",\n    ]\n    for turn in turns:\n        lines += [\n            \"\",\n            f\"### T{turn[''n'']} — {turn[''elapsed'']}s, {len(turn[''tools''])} 次工具\",\n            f\"U: {turn[''message''][:160]}\",\n            f\"tools: {turn[''tools'']}\",\n            f\"A ({len(turn[''answer''])} 字): {turn[''answer''][:700]}\"\n            + (f\"\\n⚠️ 本轮中断: {turn[''note'']}\" if turn.get(\"note\") else \"\"),\n        ]\n    lines += [\"\", \"---\", \"逐条对 rubric 判 pass/fail 时引用上面这段，不要凭印象。\"]\n    return \"\\n\".join(lines)", "args_schema": {"agent_id": {"type": "integer", "description": ""}, "probe": {"type": "string", "description": "", "default": ""}, "probes": {"type": "array", "description": "", "default": null}, "max_seconds": {"type": "integer", "description": "", "default": 120}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}, "probe": {"type": "string", "description": "", "default": ""}, "probes": {"type": "array", "description": "", "default": null}, "max_seconds": {"type": "integer", "description": "", "default": 120}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "agents", "order": 29, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 03:15:07.803681+00:00', '2026-11-01 07:38:37.029921+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'test_agent');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'update_agent', 'Update Agent Config', 'Patch an existing agent by id. Only the fields you pass change. Requires approval.

Prefer ``middleware_patch`` over ``middleware`` when changing one step of a
handoff or one entry of a HITL policy: it merges, so the rest of the
middleware stays exactly as it is.

Read it first with pg_get_agent and change one thing at a time, so a failing
test can be attributed to a specific edit.', 'python_function', 'custom', '{"function_name": "update_agent", "code": "# --- imports ---\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nAGENT_BUILDER_APPROVED = \"[rejected] this write needs an approval decision — the tool did not run\"\n\ndef _in_agent_run() -> bool:\n    \"\"\"True when this tool call is executing inside a LangGraph run.\n\n    `interrupt()` raises outside a checkpointed graph, and these tools are also\n    callable from the UI and from scripts — those paths must not try to pause.\n    \"\"\"\n    try:\n        from langchain_core.runnables.config import ensure_config\n\n        cfg = ensure_config() or {}\n        return bool((cfg.get(\"configurable\") or {}).get(\"thread_id\"))\n    except Exception:\n        return False\n\ndef _approval_gate(tool_name: str, payload: dict, description: str) -> str | None:\n    \"\"\"Pause for a human decision. Returns None to proceed, or a refusal string.\"\"\"\n    if not _in_agent_run():\n        return None\n\n    from langgraph.types import interrupt\n\n    decision = interrupt(\n        {\n            \"action_requests\": [\n                {\"name\": tool_name, \"args\": payload, \"description\": description}\n            ],\n            \"review_configs\": [\n                {\"action_name\": tool_name, \"allowed_decisions\": [\"approve\", \"reject\"]}\n            ],\n        }\n    )\n\n    if isinstance(decision, dict) and \"decisions\" in decision:\n        flat = decision.get(\"decisions\") or []\n        decision = flat[0] if flat else {}\n    if isinstance(decision, list):\n        decision = decision[0] if decision else {}\n    kind = decision.get(\"type\") if isinstance(decision, dict) else decision\n\n    if kind == \"approve\":\n        return None\n    if kind == \"reject\":\n        return f\"[rejected by human] {decision.get(''message'') or ''no reason given''}\"\n    return AGENT_BUILDER_APPROVED\n\ndef _agent_config_payload(kind: str, cfg: dict) -> dict:\n    \"\"\"The DeepAgentConfig for a new agent, normal or deep.\n\n    `kind=\"normal\"` flips `use_deepagents` off: the platform then assembles the\n    prompt (guardrails + tool enforcement) instead of taking ours verbatim, and\n    the harness file tools no longer arrive for free — a normal agent that needs\n    to write files must list `write_file` itself.\n    \"\"\"\n    from models.deep_agent import (\n        DeepAgentConfig,\n        MiddlewareConfig,\n        SubAgentConfig,\n        create_default_backend_config,\n        create_default_guardrails_config,\n        create_default_middleware_config,\n    )\n\n    subagents = []\n    for sub in cfg.get(\"subagents\") or []:\n        if not isinstance(sub, dict) or not sub.get(\"name\"):\n            continue\n        subagents.append(\n            SubAgentConfig(\n                name=sub[\"name\"],\n                description=sub.get(\"description\") or \"\",\n                system_prompt=sub.get(\"system_prompt\") or \"\",\n                tools=list(sub.get(\"tools\") or []),\n                middleware=list(sub.get(\"middleware\") or []),\n                interrupt_on=sub.get(\"interrupt_on\") or {},\n            )\n        )\n\n    middleware = []\n    for mw in cfg.get(\"middleware\") or []:\n        if isinstance(mw, dict) and mw.get(\"type\"):\n            middleware.append(\n                MiddlewareConfig(\n                    type=mw[\"type\"],\n                    enabled=mw.get(\"enabled\", True),\n                    config=mw.get(\"config\") or {},\n                )\n            )\n    # None = \"I did not say\" → platform defaults. [] = \"I said none\" → none.\n    # Collapsing the two made a template that says \"no middleware\" silently get\n    # todo_list + filesystem + subagent (found by Agent Builder, 2026-11-01).\n    if cfg.get(\"middleware\") is None:\n        middleware = create_default_middleware_config()\n\n    return DeepAgentConfig(\n        model=cfg.get(\"model\") or None,\n        temperature=cfg.get(\"temperature\") if cfg.get(\"temperature\") is not None else 0.3,\n        system_prompt=(cfg.get(\"system_prompt\") or \"\").strip(),\n        native_tools=list(cfg.get(\"native_tools\") or []),\n        cli_tools=[],\n        custom_tools=[],\n        skills=cfg.get(\"skills\"),\n        tools=[],\n        use_deepagents=(kind != \"normal\"),\n        middleware=middleware,\n        subagents=subagents,\n        mcp_servers=cfg.get(\"mcp_servers\") or None,\n        tool_params=cfg.get(\"tool_params\") or None,\n        backend=create_default_backend_config(),\n        guardrails=create_default_guardrails_config(),\n    )\n\ndef _apply_config(agent, cfg_obj) -> list[str]:\n    \"\"\"Write a DeepAgentConfig onto the template row; returns the fields saved.\"\"\"\n    from sqlalchemy.orm.attributes import flag_modified\n\n    dumped = cfg_obj.dict()\n    agent.config = dumped\n    agent.middleware_config = [m.dict() for m in cfg_obj.middleware]\n    agent.subagents_config = [s.dict() for s in cfg_obj.subagents]\n    agent.backend_config = cfg_obj.backend.dict()\n    agent.guardrails_config = cfg_obj.guardrails.dict()\n    flag_modified(agent, \"config\")\n    saved = [\"model\", \"temperature\", \"system_prompt\", \"native_tools\", \"middleware\"]\n    if cfg_obj.subagents:\n        saved.append(\"subagents\")\n    if cfg_obj.mcp_servers:\n        saved.append(\"mcp_servers\")\n    if cfg_obj.tool_params:\n        saved.append(\"tool_params\")\n    if cfg_obj.skills:\n        saved.append(\"skills\")\n    return saved\n\ndef _as_list(value, sep: str = \",\") -> list:\n    \"\"\"Accept a real list, a JSON array string, or CSV — models send all three.\n\n    The tool schema says \"array\" now, but a model that has seen older catalog\n    text still emits \"web_search,tavily_search\". Coercing here keeps the build\n    correct instead of silently creating an agent whose tools are the\n    characters of that string (which happened once).\n    \"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [str(v).strip() for v in value if str(v).strip()]\n    if isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        if text.startswith(\"[\"):\n            try:\n                import json as _json\n\n                parsed = _json.loads(text)\n                if isinstance(parsed, list):\n                    return [str(v).strip() for v in parsed if str(v).strip()]\n            except Exception:\n                pass\n        return [part.strip() for part in text.split(sep) if part.strip()]\n    return [str(value)]\n\ndef _as_dict(value):\n    \"\"\"Accept a dict or a JSON object string.\"\"\"\n    if value is None:\n        return None\n    if isinstance(value, dict):\n        return value\n    if isinstance(value, str) and value.strip().startswith(\"{\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return parsed if isinstance(parsed, dict) else None\n        except Exception:\n            return None\n    return None\n\ndef _as_list_of_dicts(value) -> list:\n    \"\"\"Accept a list, or a JSON array string (subagents/middleware).\"\"\"\n    if value is None:\n        return []\n    if isinstance(value, (list, tuple)):\n        return [v for v in value if isinstance(v, dict)]\n    if isinstance(value, str) and value.strip().startswith(\"[\"):\n        try:\n            import json as _json\n\n            parsed = _json.loads(value)\n            return [v for v in parsed if isinstance(v, dict)] if isinstance(parsed, list) else []\n        except Exception:\n            return []\n    return []\n\ndef _merge_middleware_patch(middleware: list, patch) -> list:\n    \"\"\"Merge a per-type middleware patch into an existing middleware list.\n\n    `update_agent(middleware=...)` replaces the whole field, so changing one\n    handoff step means reproducing every other step verbatim — a caller that has\n    only a stale copy either clobbers the agent or (correctly) refuses to act.\n    A patch says just what changes:\n\n        {\"handoff\": {\"steps\": {\"warranty_collector\": {\"system_prompt\": \"…\"}}}}\n        {\"hitl\": {\"interrupt_on\": {\"write_file\": True}}}\n\n    Steps merge one level deep, so touching one step leaves the others alone.\n    A type that is not present yet is appended.\n    \"\"\"\n    patch = _as_dict(patch) or {}\n    merged = [dict(m) if isinstance(m, dict) else m for m in (middleware or [])]\n    for mtype, spec in patch.items():\n        if not isinstance(spec, dict):\n            continue\n        target = None\n        for m in merged:\n            if isinstance(m, dict) and m.get(\"type\") == mtype:\n                target = m\n                break\n        if target is None:\n            merged.append({\"type\": mtype, \"enabled\": True, \"config\": dict(spec)})\n            continue\n        conf = dict(target.get(\"config\") or {})\n        for key, value in spec.items():\n            if key == \"steps\" and isinstance(value, dict):\n                steps = dict(conf.get(\"steps\") or {})\n                for step_name, step_spec in value.items():\n                    if not isinstance(step_spec, dict):\n                        continue\n                    step = dict(steps.get(step_name) or {})\n                    step.update(step_spec)\n                    steps[step_name] = step\n                conf[\"steps\"] = steps\n            else:\n                conf[key] = value\n        target[\"config\"] = conf\n        target.setdefault(\"enabled\", True)\n    return merged\n\ndef update_agent(agent_id: int,\n                 system_prompt: str | None = None,\n                 native_tools: list[str] | None = None,\n                 skills: list[str] | None = None,\n                 subagents: list[dict] | None = None,\n                 middleware: list[dict] | None = None,\n                 mcp_servers: dict | None = None,\n                 middleware_patch: dict | None = None,\n                 model: str | None = None,\n                 temperature: float | None = None,\n                 agent_docs: dict | None = None) -> str:\n    \"\"\"Patch an existing agent by id. Only the fields you pass change. Requires approval.\n\n    Prefer ``middleware_patch`` over ``middleware`` when changing one step of a\n    handoff or one entry of a HITL policy: it merges, so the rest of the\n    middleware stays exactly as it is.\n\n    Read it first with pg_get_agent and change one thing at a time, so a failing\n    test can be attributed to a specific edit.\n    \"\"\"\n    from db.database import SessionLocal\n    from models.deep_agent import DeepAgentTemplate\n\n    native_tools = _as_list(native_tools) if native_tools is not None else None\n    middleware_patch = _as_dict(middleware_patch) if middleware_patch is not None else None\n    skills = _as_list(skills) if skills is not None else None\n    subagents = _as_list_of_dicts(subagents) if subagents is not None else None\n    middleware = _as_list_of_dicts(middleware) if middleware is not None else None\n    mcp_servers = _as_dict(mcp_servers) if mcp_servers is not None else None\n    agent_docs = _as_dict(agent_docs) if agent_docs is not None else None\n\n    refusal = _approval_gate(\n        \"update_agent\",\n        {\"agent_id\": agent_id, \"fields\": [k for k, v in {\n            \"system_prompt\": system_prompt, \"native_tools\": native_tools, \"skills\": skills,\n            \"subagents\": subagents, \"middleware\": middleware, \"mcp_servers\": mcp_servers,\n            \"middleware_patch\": middleware_patch,\n            \"model\": model, \"temperature\": temperature, \"agent_docs\": agent_docs,\n        }.items() if v is not None]},\n        f\"Update agent {agent_id}\",\n    )\n    if refusal:\n        return refusal\n\n    db = SessionLocal()\n    try:\n        agent = db.query(DeepAgentTemplate).filter(DeepAgentTemplate.id == agent_id).first()\n        if not agent:\n            return f\"❌ Agent with id={agent_id} not found.\"\n        if getattr(agent, \"is_public\", False):\n            return (\"❌ 拒绝修改 public agent。public 的是共享基线，改它会影响所有人；\"\n                    \"请先复制成私有 agent（create_agent）再改。\")\n\n        cur = dict(agent.config or {})\n        before = {k: cur.get(k) for k in (\"model\", \"temperature\", \"native_tools\")}\n        merged = {\n            \"system_prompt\": system_prompt if system_prompt is not None else cur.get(\"system_prompt\"),\n            \"native_tools\": native_tools if native_tools is not None else cur.get(\"native_tools\"),\n            \"skills\": skills if skills is not None else cur.get(\"skills\"),\n            \"model\": model if model is not None else cur.get(\"model\"),\n            \"temperature\": temperature if temperature is not None else cur.get(\"temperature\"),\n            \"subagents\": subagents if subagents is not None else cur.get(\"subagents\"),\n            \"middleware\": (\n            _merge_middleware_patch(cur.get(\"middleware\") or [], middleware_patch)\n            if middleware_patch is not None\n            else (middleware if middleware is not None else cur.get(\"middleware\"))\n        ),\n            \"mcp_servers\": mcp_servers if mcp_servers is not None else cur.get(\"mcp_servers\"),\n            \"tool_params\": cur.get(\"tool_params\"),\n        }\n        kind = \"normal\" if cur.get(\"use_deepagents\") is False else \"deep\"\n        cfg_obj = _agent_config_payload(kind, merged)\n        saved = _apply_config(agent, cfg_obj)\n        if agent_docs is not None:\n            agent.agent_docs = agent_docs\n            saved.append(\"agent_docs\")\n        db.commit()\n        db.refresh(agent)\n\n        after = {k: (agent.config or {}).get(k) for k in (\"model\", \"temperature\", \"native_tools\")}\n        return (\n            f\"✅ agent {agent_id} updated — 保存字段: {'', ''.join(saved)}\\n\"\n            f\"改前: {before}\\n改后: {after}\\n\"\n            f\"下一步: test_agent(agent_id={agent_id}, probe=...) 复测同一批 rubric 条目。\"\n        )\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to update agent: {e}\"\n    finally:\n        db.close()", "args_schema": {"agent_id": {"type": "integer", "description": ""}, "system_prompt": {"type": "string", "description": "", "default": null}, "native_tools": {"type": "array", "description": "", "default": null}, "skills": {"type": "array", "description": "", "default": null}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "middleware_patch": {"type": "object", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}}', '{"type": "object", "properties": {"agent_id": {"type": "integer", "description": ""}, "system_prompt": {"type": "string", "description": "", "default": null}, "native_tools": {"type": "array", "description": "", "default": null}, "skills": {"type": "array", "description": "", "default": null}, "subagents": {"type": "array", "description": "", "default": null}, "middleware": {"type": "array", "description": "", "default": null}, "mcp_servers": {"type": "object", "description": "", "default": null}, "middleware_patch": {"type": "object", "description": "", "default": null}, "model": {"type": "string", "description": "", "default": null}, "temperature": {"type": "number", "description": "", "default": null}, "agent_docs": {"type": "object", "description": "", "default": null}}, "required": ["agent_id"]}', 'string', NULL, '{"category": "agents", "order": 28, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'agent_management', TRUE, NULL, '["builtin", "agent_management"]', '2026-11-01 03:15:07.803678+00:00', '2026-11-01 07:03:03.334046+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'update_agent');

INSERT INTO custom_tools (tool_id, name, description, tool_type, template_type, implementation_config, input_schema, output_format, validation_rules, definition, is_template_based, is_advanced_mode, created_by, is_public, project_id, usage_count, last_used_at, error_count, last_error_at, version, parent_tool_id, category, is_builtin, requires_api_key, tags, created_at, updated_at)
SELECT 'update_skill', 'Update Skill', 'Update an existing skill in the database. Only provided fields are updated.

Args:
    skill_id: The kebab-case ID of the skill to update
    name: New human-readable name
    description: New description
    instructions: New instructions
    tags: New list of tags
    triggers: New list of triggers', 'python_function', 'custom', '{"function_name": "update_skill", "code": "# --- imports ---\n\nimport json\n\nfrom pathlib import Path\n\nfrom langchain_core.tools import InjectedToolCallId, StructuredTool, tool\n\nimport re as _re\n\n# --- logger ---\n\nimport logging\n\nlogger = logging.getLogger(\"langconfig.builtin_tool\")\n\ndef _skill_support_files(base: Path, limit: int = 40) -> list:\n    \"\"\"Files next to SKILL.md, as skill-relative paths (sorted, capped).\n\n    A skill that ships templates or reference tables is useless if the model\n    cannot see that they exist: the instructions are in the DB, the files are on\n    disk. Seen 2026-11-01 — Agent Builder rebuilt a template from memory because\n    `templates/` was invisible.\n    \"\"\"\n    if base is None or not base.is_dir():\n        return []\n    out = []\n    for path in sorted(base.rglob(\"*\")):\n        if not path.is_file() or path.name == \"SKILL.md\":\n            continue\n        out.append(str(path.relative_to(base)))\n        if len(out) >= limit:\n            break\n    return out\n\nasync def skill(skill_id: str, file: str = \"\") -> str:\n    \"\"\"Fetch a skill''s full instructions by its id — or one of its support files.\n\n    Use when the user asks about a topic that a skill covers but the skill was\n    not pre-injected into your context. Reads the skill from the library on\n    demand (progressive disclosure).\n\n    Skills may ship supporting files next to SKILL.md (templates, fact tables,\n    scripts). Those are NOT loaded with the instructions; list them with this\n    tool first (it prints `Support files:`), then ask for one by path.\n\n    Args:\n        skill_id: The skill''s id (e.g. \"web-search\", \"text-summarizer\")\n        file: Optional path inside the skill directory, e.g.\n              \"templates/T2-supervisor-experts.md\". Leave empty for the\n              instructions. Must stay inside the skill.\n    \"\"\"\n    try:\n        from core.skills.registry import get_skill_registry\n        registry = get_skill_registry()\n        if not registry._initialized:\n            await registry.initialize()\n        found = registry.get_skill(skill_id)\n        if found is None:\n            available = \", \".join(sorted(s.skill_id for s in registry.list_all())) or \"none\"\n            return f\"Error: skill ''{skill_id}'' not found. Available skills: {available}\"\n        base = Path(found.source_path) if getattr(found, \"source_path\", None) else None\n\n        if file:\n            if base is None or not base.is_dir():\n                return f\"Error: skill ''{skill_id}'' has no source directory on disk.\"\n            target = (base / file).resolve()\n            try:\n                target.relative_to(base.resolve())\n            except ValueError:\n                return f\"Error: ''{file}'' escapes skill ''{skill_id}''.\"\n            if not target.is_file():\n                listing = _skill_support_files(base)\n                return (f\"Error: ''{file}'' not found in skill ''{skill_id}''. \"\n                        f\"Support files: {'', ''.join(listing) or ''none''}\")\n            text = target.read_text(encoding=\"utf-8\", errors=\"replace\")\n            return f\"# Skill file: {skill_id}/{file}\\n\\n{text}\"\n\n        parts = [\n            f\"# Skill: {found.name}\",\n            f\"**Description:** {found.description}\",\n            \"\",\n            found.instructions,\n        ]\n        if found.examples:\n            parts += [\"\", \"**Examples:**\", found.examples]\n        if found.allowed_tools:\n            parts += [\"\", f\"**Allowed tools:** {'', ''.join(found.allowed_tools)}\"]\n        support = _skill_support_files(base) if base else []\n        if support:\n            parts += [\n                \"\",\n                \"**Support files** (not loaded above — fetch one with \"\n                f\"skill(\\\"{found.skill_id}\\\", file=\\\"<path>\\\")):\",\n                *[f\"- {f}\" for f in support],\n            ]\n        return \"\\n\".join(parts)\n    except Exception as e:\n        return f\"Error loading skill ''{skill_id}'': {e}\"\n\ndef _coerce_str_list(value) -> list[str] | None:\n    \"\"\"Normalise a model-supplied \"list\" into a real list of strings.\n\n    Why this exists: ``create_skill``/``update_skill`` declare ``tags: list[str]``\n    and ``triggers: list[str]``, but Python does not enforce annotations at\n    runtime. Models routinely pass arrays as JSON text (``''[\"a\", \"b\"]''``) or as a\n    comma-separated string (``\"a, b\"``). Stored verbatim in the JSON columns,\n    that string makes ``SkillResponse`` fail validation — which surfaced as a\n    500 on ``GET /api/skills/{id}`` while ``GET /api/skills`` hid it behind a\n    placeholder row.\n\n    Coerce at the boundary rather than trusting the type hint: an LLM is the\n    caller here, so the input is untrusted text in practice.\n    \"\"\"\n    if value is None:\n        return None\n    if isinstance(value, (list, tuple, set)):\n        items = list(value)\n    elif isinstance(value, str):\n        text = value.strip()\n        if not text:\n            return []\n        parsed = None\n        try:\n            parsed = json.loads(text)\n        except (ValueError, TypeError):\n            parsed = None\n        if isinstance(parsed, list):\n            items = parsed\n        elif isinstance(parsed, dict) or parsed is None:\n            # Not JSON, or a JSON object: fall back to splitting on commas.\n            items = text.split(\",\")\n        else:\n            items = [parsed]\n    else:\n        items = [value]\n\n    out: list[str] = []\n    for item in items:\n        if item is None:\n            continue\n        text = str(item).strip()\n        if text:\n            out.append(text)\n    return out\n\ndef update_skill(skill_id: str, name: str | None = None,\n                 description: str | None = None,\n                 instructions: str | None = None,\n                 tags: list[str] | None = None,\n                 triggers: list[str] | None = None) -> str:\n    \"\"\"Update an existing skill in the database. Only provided fields are updated.\n\n    Args:\n        skill_id: The kebab-case ID of the skill to update\n        name: New human-readable name\n        description: New description\n        instructions: New instructions\n        tags: New list of tags\n        triggers: New list of triggers\n    \"\"\"\n    from db.database import SessionLocal\n    from models.skill import Skill\n    import datetime\n    import re as _re\n\n    # Sanitize the identifier — only kebab-case ids are valid; anything else is\n    # rejected before touching the DB (defense-in-depth against odd inputs).\n    if not _re.fullmatch(r\"[a-z0-9][a-z0-9-]*\", skill_id or \"\"):\n        return f\"❌ Invalid skill_id ''{skill_id}'': use kebab-case (letters, digits, hyphens).\"\n\n    db = SessionLocal()\n    try:\n        skill = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n        if not skill:\n            return f\"❌ Skill ''{skill_id}'' not found. Use create_skill first.\"\n\n        if name is not None:\n            skill.name = name.strip()\n        if description is not None:\n            skill.description = description.strip()\n        if instructions is not None:\n            skill.instructions = instructions.strip()\n        if tags is not None:\n            skill.tags = _coerce_str_list(tags)\n        if triggers is not None:\n            skill.triggers = _coerce_str_list(triggers)\n        skill.updated_at = datetime.datetime.now(datetime.timezone.utc)\n        db.commit()\n        # Mirror to SKILL.md: the file is what a teammate receives.\n        try:\n            from core.skills.sync import db_row_to_fs\n\n            row = db.query(Skill).filter(Skill.skill_id == skill_id).first()\n            if row is not None:\n                db_row_to_fs(row)\n        except Exception as _e:  # noqa: BLE001\n            logger.warning(f\"update_skill: SKILL.md mirror skipped: {_e}\")\n        return f\"✅ Skill ''{skill_id}'' updated successfully!\"\n    except Exception as e:\n        db.rollback()\n        return f\"❌ Failed to update skill: {e}\"\n    finally:\n        db.close()", "args_schema": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}}}', '{"type": "object", "properties": {"skill_id": {"type": "string", "description": ""}, "name": {"type": "string", "description": "", "default": null}, "description": {"type": "string", "description": "", "default": null}, "instructions": {"type": "string", "description": "", "default": null}, "tags": {"type": "array", "description": "", "default": null}, "triggers": {"type": "array", "description": "", "default": null}}, "required": ["skill_id"]}', 'string', NULL, '{"category": "skills", "order": 25, "section": null, "is_concurrency_safe": true, "output_schema": null, "guard": {"approval": false, "confirmation": false}, "presentation": {}}', TRUE, TRUE, 'builtin-seeder', FALSE, NULL, 0, NULL, 0, NULL, '1.0.0', NULL, 'skills', TRUE, NULL, '["builtin", "skills"]', '2026-08-01 14:44:18.034635+00:00', '2026-11-01 07:17:45.589044+00:00'
WHERE NOT EXISTS (SELECT 1 FROM custom_tools WHERE tool_id = 'update_skill');

